if($action==='export') { $from=$_GET['from']??date('Y-m-01');$to=$_GET['to']??date('Y-m-t');$validDate=static fn(string $v):bool=>(bool)preg_match('/^\d{4}-\d{2}-\d{2}$/',$v)&&DateTimeImmutable::createFromFormat('!Y-m-d',$v)?->format('Y-m-d')===$v;if(!$validDate((string)$from)||!$validDate((string)$to)||$from>$to){http_response_code(400);exit('Rentang tanggal ekspor tidak valid.');}$st=$pdo->prepare('SELECT sm.occurred_at,sm.movement_no,sm.movement_type,p.sku,p.name product_name,w.name warehouse_name,l.location_code,b.batch_no,sm.qty_change,sm.reference_type,sm.reference_id,sm.notes FROM stock_movements sm JOIN products p ON p.id=sm.product_id JOIN warehouses w ON w.id=sm.warehouse_id LEFT JOIN locations l ON l.id=sm.location_id LEFT JOIN product_batches b ON b.id=sm.batch_id WHERE sm.occurred_at>=? AND sm.occurred_at<? ORDER BY sm.occurred_at');$st->execute([$from.' 00:00:00',date('Y-m-d',strtotime($to.' +1 day')).' 00:00:00']);header('Content-Type: text/csv; charset=UTF-8');header('Content-Disposition: attachment; filename="wms-pergerakan-'.$from.'-'.$to.'.csv"');echo "\xEF\xBB\xBF";$out=fopen('php://output','w');fputcsv($out,['Tanggal','No. Transaksi','Jenis','SKU','Produk','Gudang','Lokasi','Batch','Qty (+/-)','Referensi','ID Referensi','Catatan'],';');while($r=$st->fetch())fputcsv($out,$r,';');fclose($out);exit; }
function post_action_routes(string $do,array $post):array {
  $map=[
    'scan_session_start'=>['pivot-session'],'scan_session_capture'=>['pivot-session'],'scan_session_close'=>['pivot-session'],
    'rfid_mapping_save'=>['rfid-map'],'rfid_mapping_deactivate'=>['rfid-map'],
    'role_save'=>['roles'],'role_delete'=>['roles'],'user_add'=>['roles'],'user_role'=>['roles'],'user_toggle'=>['roles'],
    'product_add'=>['products'],'warehouse_add'=>['warehouses'],'location_add'=>['locations'],'supplier_add'=>['suppliers'],
    'dock_add'=>['schedule'],'appointment_create'=>['schedule'],'appointment_status'=>['schedule'],
    'transfer_create'=>['transfers','transfer-bin'],
  ];
  if($do==='stock_post') {
    $direction=$post['direction']??'INBOUND';
    return $direction==='INBOUND'?['inbound','orders']:($direction==='OUTBOUND'?['outbound','orders']:[]);
  }
  return $map[$do]??[];
}
if($_SERVER['REQUEST_METHOD']==='POST') {
