function count_sql(PDO $p,string $sql):int{return (int)$p->query($sql)->fetchColumn();}
/** Current low-stock alerts are computed from committed inventory balances on every request. */
function stock_alert_rows(PDO $p,int $limit=100):array{
  $limit=max(1,min(500,$limit));
  $sql="SELECT p.id product_id,p.sku,p.name product_name,p.uom,p.safety_stock,p.reorder_point,
    COALESCE(SUM(i.qty_on_hand),0) on_hand,COALESCE(SUM(i.qty_reserved),0) reserved,
    COALESCE(SUM(i.qty_on_hand-i.qty_reserved),0) available,
    GREATEST(p.safety_stock,p.reorder_point) threshold_qty,
    COUNT(DISTINCT CASE WHEN i.qty_on_hand>0 THEN i.warehouse_id END) warehouses_with_stock
    FROM products p LEFT JOIN inventory i ON i.product_id=p.id
    WHERE p.is_active=1 GROUP BY p.id,p.sku,p.name,p.uom,p.safety_stock,p.reorder_point
    HAVING GREATEST(p.safety_stock,p.reorder_point)>0 AND COALESCE(SUM(i.qty_on_hand-i.qty_reserved),0)<=GREATEST(p.safety_stock,p.reorder_point) ORDER BY (COALESCE(SUM(i.qty_on_hand-i.qty_reserved),0)<=0) DESC,(GREATEST(p.safety_stock,p.reorder_point)-COALESCE(SUM(i.qty_on_hand-i.qty_reserved),0)) DESC,p.name LIMIT {$limit}";
  return $p->query($sql)->fetchAll();
}
function page_dashboard(PDO $p):void{
  $products=count_sql($p,'SELECT COUNT(*) FROM products WHERE is_active=1');
  $wh=count_sql($p,'SELECT COUNT(*) FROM warehouses WHERE is_active=1');
  $qty=(float)$p->query('SELECT COALESCE(SUM(qty_on_hand),0) FROM inventory')->fetchColumn();
  $low=count(stock_alert_rows($p,500));
  $monthStart=date('Y-m-01'); $nextMonth=date('Y-m-01',strtotime('+1 month'));
  $in=$p->prepare("SELECT COALESCE(SUM(qty_change),0) FROM stock_movements WHERE qty_change>0 AND occurred_at>=? AND occurred_at<?");$in->execute([$monthStart,$nextMonth]);$monthIn=(float)$in->fetchColumn();
  $out=$p->prepare("SELECT COALESCE(SUM(-qty_change),0) FROM stock_movements WHERE qty_change<0 AND occurred_at>=? AND occurred_at<?");$out->execute([$monthStart,$nextMonth]);$monthOut=(float)$out->fetchColumn();
  $moves=$p->query('SELECT sm.*,p.sku,p.name product_name,w.name warehouse_name FROM stock_movements sm JOIN products p ON p.id=sm.product_id JOIN warehouses w ON w.id=sm.warehouse_id ORDER BY sm.occurred_at DESC LIMIT 5')->fetchAll();
  $warehouseRows=$p->query('SELECT w.name,COALESCE(SUM(i.qty_on_hand),0) qty FROM warehouses w LEFT JOIN inventory i ON i.warehouse_id=w.id WHERE w.is_active=1 GROUP BY w.id,w.name ORDER BY qty DESC LIMIT 5')->fetchAll();
  $top=$p->query('SELECT p.sku,p.name,COALESCE(SUM(i.qty_on_hand),0) qty FROM products p LEFT JOIN inventory i ON i.product_id=p.id WHERE p.is_active=1 GROUP BY p.id,p.sku,p.name ORDER BY qty DESC LIMIT 5')->fetchAll();
  $pending=$p->query("SELECT o.order_no,o.direction,o.status,o.priority,w.name warehouse_name,o.created_at FROM orders o JOIN warehouses w ON w.id=o.warehouse_id WHERE o.status NOT IN ('RECEIVED','DISPATCHED','CANCELLED','COMPLETED') ORDER BY o.created_at DESC LIMIT 5")->fetchAll();
  $maxWh=max(array_merge([1.0],array_map(fn($r)=>(float)$r['qty'],$warehouseRows)));$maxTop=max(array_merge([1.0],array_map(fn($r)=>(float)$r['qty'],$top)));
  page_title('Dasbor WMS','Ringkasan operasional gudang secara real-time.','<div class="toolbar no-print"><button class="btn secondary" type="button" onclick="window.print()">▤ Print</button><a class="btn secondary" href="?action=reports">Laporan</a><a class="btn primary" href="?action=orders">＋ Transaksi baru</a></div>');
  echo '<div class="wms-kpis"><article class="kpi-card"><div class="kpi-top"><span class="kpi-icon green">⇅</span><span class="kpi-label">Barang Masuk</span></div><strong>'.number_format($monthIn,0,',','.').'</strong><small>Total kuantitas bulan ini</small><span class="kpi-foot green-text">Penerimaan periode berjalan</span></article><article class="kpi-card"><div class="kpi-top"><span class="kpi-icon red">↗</span><span class="kpi-label">Barang Keluar</span></div><strong>'.number_format($monthOut,0,',','.').'</strong><small>Total kuantitas bulan ini</small><span class="kpi-foot red-text">Pengeluaran periode berjalan</span></article><article class="kpi-card"><div class="kpi-top"><span class="kpi-icon blue">▦</span><span class="kpi-label">Stok Inventaris</span></div><strong>'.number_format($qty,0,',','.').'</strong><small>Total unit on hand</small><span class="kpi-foot">'.number_format($products).' SKU aktif</span></article><article class="kpi-card"><div class="kpi-top"><span class="kpi-icon purple">⌂</span><span class="kpi-label">Gudang Aktif</span></div><strong>'.number_format($wh).'</strong><small>Node fulfillment</small><span class="kpi-foot">'.number_format($low).' SKU perlu diperiksa</span></article><article class="kpi-card"><div class="kpi-top"><span class="kpi-icon orange">!</span><span class="kpi-label">Safety Stock</span></div><strong>'.number_format($low).'</strong><small>SKU di bawah ambang · semua gudang</small><span class="kpi-foot orange-text">Perlu replenishment</span></article></div>';
  $alerts=stock_alert_rows($p,5);
  echo '<section class="panel stock-alert-panel"><div class="panel-head"><div><h3>Notifikasi stok menipis</h3><p>Dihitung dari saldo tersedia lintas gudang dan ambang safety/reorder point.</p></div><a class="btn secondary" href="?action=stock-control">Lihat semua alert ('.number_format($low).')</a></div>';
  if(!$alerts)echo '<div class="alert success">Tidak ada SKU aktif di bawah ambang stok saat ini.</div>';
  else {echo '<div class="stock-alert-list">';foreach($alerts as $a){$critical=(float)$a['available']<=0;echo '<article class="stock-alert-item"><span class="stock-alert-indicator '.($critical?'critical':'warning').'">'.($critical?'!':'↓').'</span><div class="stock-alert-product"><strong>'.e($a['sku'].' · '.$a['product_name']).'</strong><small>Ambang '.qty_fmt($a['threshold_qty']).' '.$a['uom'].' · '.(int)$a['warehouses_with_stock'].' gudang memiliki stok</small></div><div class="stock-alert-qty"><strong>'.qty_fmt($a['available']).'</strong><small>Tersedia</small></div></article>'; }echo '</div>';}
  echo '</section>';
  echo '<div class="dash-grid dash-middle"><section class="panel chart-panel"><div class="panel-head"><div><h3>Pergerakan Stok Bulanan</h3><p>Akumulasi barang masuk dan keluar · '.e(date('F Y')).'</p></div><a href="?action=movements">Lihat semua →</a></div><div class="movement-bars"><div class="axis-labels"><span>Qty</span><span>0</span></div><div class="bars-area">';
  $months=[];for($i=5;$i>=0;$i--){$d=strtotime(date('Y-m-01').' -'.$i.' months');$a=date('Y-m-01',$d);$b=date('Y-m-01',strtotime($a.' +1 month'));$q=$p->prepare('SELECT COALESCE(SUM(CASE WHEN qty_change>0 THEN qty_change ELSE 0 END),0) ins,COALESCE(SUM(CASE WHEN qty_change<0 THEN -qty_change ELSE 0 END),0) outs FROM stock_movements WHERE occurred_at>=? AND occurred_at<?');$q->execute([$a,$b]);$v=$q->fetch();$months[]=['label'=>date('M',$d),'in'=>(float)$v['ins'],'out'=>(float)$v['outs']];}
  $barMax=max(array_merge([1.0],array_map(fn($m)=>max((float)$m['in'],(float)$m['out']),$months)));foreach($months as $m){$hi=max(4,(int)round($m['in']/$barMax*100));$ho=max(4,(int)round($m['out']/$barMax*100));echo '<div class="month-bars" title="'.e($m['label'].' · Masuk '.$m['in'].' · Keluar '.$m['out']).'"><div class="bar-pair"><i class="bar-in" style="height:'.$hi.'%"></i><i class="bar-out" style="height:'.$ho.'%"></i></div><span>'.e($m['label']).'</span></div>';}
  echo '</div></div><div class="chart-legend"><span><i class="legend-dot blue-dot"></i>Barang masuk</span><span><i class="legend-dot pink-dot"></i>Barang keluar</span></div></section><section class="panel warehouse-panel"><div class="panel-head"><div><h3>Stok per Gudang</h3><p>Distribusi unit on hand</p></div><a href="?action=warehouses">Kelola →</a></div><div class="warehouse-content"><div class="donut-chart"><div><strong>'.number_format($qty,0,',','.').'</strong><small>Total stok</small></div></div><div class="warehouse-legend">';$colors=['#2687f5','#14c69a','#ffae32','#fa5475','#bd55e9'];foreach($warehouseRows as $i=>$r){$pct=$qty>0?(float)$r['qty']/$qty*100:0;echo '<div><i style="background:'.$colors[$i%count($colors)].'"></i><span>'.e($r['name']).'<small>'.number_format((float)$r['qty'],0,',','.').' · '.number_format($pct,1,',','.').'%</small></span></div>';}if(!$warehouseRows)echo '<p class="muted">Belum ada gudang aktif.</p>';echo '</div></div></section><section class="panel top-products"><div class="panel-head"><div><h3>Produk dengan Stok Terbesar</h3><p>Berdasarkan kuantitas on hand</p></div><a href="?action=inventory">Inventaris →</a></div><div class="top-product-list">';foreach($top as $i=>$r){$pct=(int)round((float)$r['qty']/$maxTop*100);echo '<div class="top-product"><span class="product-rank">'.($i+1).'</span><div class="product-info"><strong>'.e($r['name']).'</strong><small>'.e($r['sku']).'</small><div class="progress-track"><i class="progress-fill fill-'.($i+1).'" style="width:'.$pct.'%"></i></div></div><b>'.number_format((float)$r['qty'],0,',','.').'</b></div>';}if(!$top)echo '<p class="muted">Belum ada data produk.</p>';echo '</div></section></div>';
  echo '<div class="dash-grid dash-bottom"><section class="panel"><div class="panel-head"><div><h3>Menunggu Proses</h3><p>Order yang belum selesai</p></div><a href="?action=orders">Semua order →</a></div>';table(['Dokumen','Jenis','Gudang','Prioritas','Status'],array_map(fn($r)=>[$r['order_no'],$r['direction'],$r['warehouse_name'],$r['priority'],$r['status']],$pending));echo '</section><section class="panel"><div class="panel-head"><div><h3>Pergerakan Terbaru</h3><p>Aktivitas stok terbaru</p></div><a href="?action=movements">Riwayat →</a></div>';table(['Waktu','Nomor','Produk','Gudang','Qty'],array_map(fn($r)=>[date('d/m H:i',strtotime($r['occurred_at'])),$r['movement_type'],$r['sku'].' · '.$r['product_name'],$r['warehouse_name'],qty_fmt($r['qty_change'])],$moves));echo '</section></div>';
}
function table(array $heads,array $rows):void{echo '<div class="table-wrap"><table><thead><tr>';foreach($heads as $h)echo '<th>'.e($h).'</th>';echo '</tr></thead><tbody>';if(!$rows)echo '<tr><td class="empty" colspan="'.count($heads).'">Belum ada data. Mulai dengan menambahkan data master.</td></tr>';foreach($rows as $r){echo '<tr>';foreach($r as $v)echo '<td>'.e($v).'</td>';echo '</tr>';}echo '</tbody></table></div>';}
function qty_fmt($n):string{return ((float)$n>0?'+':'').number_format((float)$n,3,',','.');}
function form_start():void{echo '<form class="inline-form" method="post"><input type="hidden" name="_csrf" value="'.e(csrf_token()).'">';}
function page_products(PDO $p):void{page_title('Master Produk','Kelola katalog SKU, barcode, satuan, serta aturan batch/serial/expiry.','<button class="btn primary" form="product-form">＋ Simpan produk</button>');echo '<section class="panel"><form id="product-form" method="post" class="form-grid"><input type="hidden" name="_csrf" value="'.e(csrf_token()).'"><input type="hidden" name="do" value="product_add"><label>SKU *<input name="sku" required maxlength="80"></label><label>Nama produk *<input name="name" required maxlength="200"></label><label>Barcode<input name="barcode"></label><label>Kategori<input name="category"></label><label>Satuan<select name="uom"><option>PCS</option><option>BOX</option><option>KG</option><option>L</option><option>SET</option></select></label><label>Mode tracking<select name="tracking_mode"><option value="NONE">Tanpa tracking</option><option value="BATCH">Batch</option><option value="SERIAL">Serial number</option><option value="BATCH_EXPIRY">Batch + expiry</option><option value="SERIAL_EXPIRY">Serial + expiry</option></select></label><label>Safety stock<input type="number" min="0" step="0.001" name="safety_stock" value="0"></label><label>Buffer stock<input type="number" min="0" step="0.001" name="buffer_stock" value="0"></label><label>Reorder point<input type="number" min="0" step="0.001" name="reorder_point" value="0"></label><label class="span-2">Deskripsi<input name="description"></label></form></section><section class="panel"><div class="panel-head"><div><h3>Daftar produk</h3><p>Data master terdaftar</p></div><span class="chip">'.count_sql($p,'SELECT COUNT(*) FROM products').' SKU</span></div>'; $rows=$p->query('SELECT sku,name,barcode,category,uom,tracking_mode,safety_stock,buffer_stock,is_active FROM products ORDER BY name')->fetchAll();table(['SKU','Nama produk','Barcode','Kategori','Satuan','Tracking','Safety','Buffer','Status'],array_map(fn($r)=>[$r['sku'],$r['name'],$r['barcode']?:'—',$r['category']?:'—',$r['uom'],$r['tracking_mode'],$r['safety_stock'],$r['buffer_stock'],$r['is_active']?'Aktif':'Nonaktif'],$rows));echo '</section>';}
function page_warehouses(PDO $p):void{page_title('Gudang','Kelola gudang, toko, dan node fulfillment.','<button class="btn primary" form="wh-form">＋ Tambah gudang</button>');echo '<section class="panel"><form id="wh-form" method="post" class="form-grid"><input type="hidden" name="_csrf" value="'.e(csrf_token()).'"><input type="hidden" name="do" value="warehouse_add"><label>Kode gudang *<input name="warehouse_code" required></label><label>Nama gudang *<input name="name" required></label><label class="span-2">Alamat<textarea name="address" rows="2"></textarea></label><div><button class="btn primary">Simpan gudang</button></div></form></section><section class="panel">';$rows=$p->query('SELECT w.warehouse_code,w.name,w.address,w.is_active,COUNT(l.id) location_count FROM warehouses w LEFT JOIN locations l ON l.warehouse_id=w.id GROUP BY w.id ORDER BY w.name')->fetchAll();table(['Kode','Nama','Alamat','Lokasi','Status'],array_map(fn($r)=>[$r['warehouse_code'],$r['name'],$r['address']?:'—',$r['location_count'],$r['is_active']?'Aktif':'Nonaktif'],$rows));echo '</section>';}
function page_locations(PDO $p):void{$wh=$p->query('SELECT id,name,warehouse_code FROM warehouses WHERE is_active=1 ORDER BY name')->fetchAll();page_title('Lokasi penyimpanan','Atur zone, aisle, rack, shelf, bin, serta tipe lokasi.','<button class="btn primary" form="loc-form">＋ Tambah lokasi</button>');echo '<section class="panel"><form id="loc-form" method="post" class="form-grid"><input type="hidden" name="_csrf" value="'.e(csrf_token()).'"><input type="hidden" name="do" value="location_add"><label>Gudang *<select name="warehouse_id" required>';foreach($wh as $w)echo '<option value="'.e($w['id']).'">'.e($w['warehouse_code'].' · '.$w['name']).'</option>';echo '</select></label><label>Kode lokasi *<input name="location_code" required placeholder="A-01-R02-B01"></label><label>Zona<input name="zone"></label><label>Aisle<input name="aisle"></label><label>Rack<input name="rack"></label><label>Shelf<input name="shelf"></label><label>Bin<input name="bin_code"></label><label>Tipe<select name="location_type"><option>STORAGE</option><option>PICKING</option><option>RECEIVING</option><option>PACKING</option><option>DISPATCH</option><option>QUARANTINE</option><option>RETURNS</option></select></label></form></section><section class="panel">';$rows=$p->query('SELECT w.name warehouse_name,l.location_code,l.zone,l.aisle,l.rack,l.shelf,l.bin_code,l.location_type,l.is_active FROM locations l JOIN warehouses w ON w.id=l.warehouse_id ORDER BY w.name,l.location_code')->fetchAll();table(['Gudang','Kode lokasi','Zona','Aisle','Rack','Shelf','Bin','Tipe','Status'],array_map(fn($r)=>[$r['warehouse_name'],$r['location_code'],$r['zone']?:'—',$r['aisle']?:'—',$r['rack']?:'—',$r['shelf']?:'—',$r['bin_code']?:'—',$r['location_type'],$r['is_active']?'Aktif':'Nonaktif'],$rows));echo '</section>';}
function page_suppliers(PDO $p):void{page_title('Pemasok','Master pemasok untuk penerimaan barang dan referensi inbound.','<button class="btn primary" form="sup-form">＋ Tambah pemasok</button>');echo '<section class="panel"><form id="sup-form" method="post" class="form-grid"><input type="hidden" name="_csrf" value="'.e(csrf_token()).'"><input type="hidden" name="do" value="supplier_add"><label>Kode pemasok *<input name="supplier_code" required></label><label>Nama pemasok *<input name="name" required></label><label>Kontak<input name="contact_person"></label><label>Telepon<input name="phone"></label><label>Email<input type="email" name="email"></label><label>Alamat<input name="address"></label></form></section><section class="panel">';$rows=$p->query('SELECT supplier_code,name,contact_person,phone,email,is_active FROM suppliers ORDER BY name')->fetchAll();table(['Kode','Pemasok','Kontak','Telepon','Email','Status'],array_map(fn($r)=>[$r['supplier_code'],$r['name'],$r['contact_person']?:'—',$r['phone']?:'—',$r['email']?:'—',$r['is_active']?'Aktif':'Nonaktif'],$rows));echo '</section>';}
function page_inventory(PDO $p):void{page_title('Inventaris','Stok per SKU, gudang, lokasi, batch, dan jumlah tersedia.');$rows=$p->query('SELECT p.sku,p.name product_name,w.name warehouse_name,l.location_code,b.batch_no,b.expiry_date,i.qty_on_hand,i.qty_reserved,(i.qty_on_hand-i.qty_reserved) available,p.safety_stock FROM inventory i JOIN products p ON p.id=i.product_id JOIN warehouses w ON w.id=i.warehouse_id LEFT JOIN locations l ON l.id=i.location_id LEFT JOIN product_batches b ON b.id=i.batch_id ORDER BY p.name,w.name,l.location_code')->fetchAll();table(['SKU','Produk','Gudang','Lokasi','Batch','Expiry','On hand','Reserved','Tersedia','Safety stock'],array_map(fn($r)=>[$r['sku'],$r['product_name'],$r['warehouse_name'],$r['location_code']?:'—',$r['batch_no']?:'—',$r['expiry_date']?:'—',$r['qty_on_hand'],$r['qty_reserved'],$r['available'],$r['safety_stock']],$rows));}
function page_movements(PDO $p):void{page_title('Pergerakan stok','Ledger pergerakan yang menjadi sumber audit inventory.');$rows=$p->query('SELECT sm.occurred_at,sm.movement_no,sm.movement_type,p.sku,p.name product_name,w.name warehouse_name,sm.qty_change,sm.notes FROM stock_movements sm JOIN products p ON p.id=sm.product_id JOIN warehouses w ON w.id=sm.warehouse_id ORDER BY sm.occurred_at DESC LIMIT 500')->fetchAll();table(['Waktu','Nomor','Jenis','SKU','Produk','Gudang','Qty (+/-)','Catatan'],array_map(fn($r)=>[date('d/m/Y H:i',strtotime($r['occurred_at'])),$r['movement_no'],$r['movement_type'],$r['sku'],$r['product_name'],$r['warehouse_name'],qty_fmt($r['qty_change']),$r['notes']?:'—'],$rows));}
function page_orders(PDO $p,?string $fixedDirection=null):void{$products=$p->query('SELECT id,sku,name,barcode FROM products WHERE is_active=1 ORDER BY name')->fetchAll();$wh=$p->query('SELECT id,warehouse_code,name FROM warehouses WHERE is_active=1 ORDER BY name')->fetchAll();$sup=$p->query('SELECT id,name FROM suppliers WHERE is_active=1 ORDER BY name')->fetchAll();page_title($fixedDirection==='INBOUND'?'Logistik Masuk':'Inbound & Outbound',$fixedDirection==='INBOUND'?'Penerimaan menambah stok, membuat order penerimaan, dan menulis ledger secara atomik.':'Catat barang masuk atau keluar. Setiap posting mengubah saldo, order, item order, ledger, dashboard, dan laporan.','<span class="chip">Posting atomik</span>');echo '<section class="panel"><form method="post" class="form-grid"><input type="hidden" name="_csrf" value="'.e(csrf_token()).'"><input type="hidden" name="do" value="stock_post">'.($fixedDirection?'<input type="hidden" name="direction" value="'.e($fixedDirection).'">':'<label>Jenis transaksi<select name="direction"><option value="INBOUND">Barang masuk</option><option value="OUTBOUND">Barang keluar</option></select></label>');echo '<label>Gudang<select name="warehouse_id" required>';foreach($wh as $w)echo '<option value="'.e($w['id']).'">'.e($w['warehouse_code'].' · '.$w['name']).'</option>';echo '</select></label><label>Barcode / SKU scan<input class="product-code-scan" data-product-target="stock-post-product" placeholder="Scan barcode / QR / SKU" autocomplete="off"></label><label>Produk<select id="stock-post-product" name="product_id" required>';foreach($products as $v)echo '<option value="'.e($v['id']).'" data-sku="'.e($v['sku']).'" data-barcode="'.e($v['barcode']??'').'">'.e($v['sku'].' · '.$v['name']).'</option>';echo '</select></label><label>Lokasi<select name="location_id"><option value="">Tanpa lokasi spesifik</option>';foreach($p->query('SELECT l.id,l.location_code,w.name warehouse_name FROM locations l JOIN warehouses w ON w.id=l.warehouse_id WHERE l.is_active=1 ORDER BY w.name,l.location_code') as $l)echo '<option value="'.e($l['id']).'">'.e($l['warehouse_name'].' / '.$l['location_code']).'</option>';echo '</select></label><label>Qty *<input type="number" name="qty" min="0.001" step="0.001" required></label><label>Nomor batch (opsional)<input name="batch_no"></label><label>Tanggal expiry<input type="date" name="expiry_date"></label><label>Referensi<input name="reference_no" placeholder="PO / SO / DO"></label><label class="span-2">Catatan<input name="notes"></label><div><button class="btn primary">Posting transaksi</button></div></form><p class="muted">Barang keluar ditolak jika stok tersedia tidak mencukupi. Untuk produk yang membutuhkan serial number, input serial individual perlu diaktifkan pada proses lanjutan sebelum go-live.</p></section><section class="panel"><div class="panel-head"><div><h3>Order operasional</h3><p>Status order dan referensi transaksi</p></div></div>'; $rows=$p->query('SELECT o.order_no,o.direction,o.order_type,o.status,o.priority,w.name warehouse_name,o.created_at FROM orders o JOIN warehouses w ON w.id=o.warehouse_id ORDER BY o.created_at DESC LIMIT 100')->fetchAll();table(['Nomor order','Arah','Tipe','Status','Prioritas','Gudang','Dibuat'],array_map(fn($r)=>[$r['order_no'],$r['direction'],$r['order_type'],$r['status'],$r['priority'],$r['warehouse_name'],date('d/m/Y H:i',strtotime($r['created_at']))],$rows));echo '</section>';}
function page_transfers(PDO $p):void{$wh=$p->query('SELECT id,warehouse_code,name FROM warehouses WHERE is_active=1 ORDER BY name')->fetchAll();$products=$p->query('SELECT id,sku,name,barcode FROM products WHERE is_active=1 ORDER BY name')->fetchAll();page_title('Transfer antar gudang','Buat permintaan transfer, dispatch, dan konfirmasi penerimaan.');echo '<section class="panel"><h3>Buat transfer</h3><form method="post" class="form-grid"><input type="hidden" name="_csrf" value="'.e(csrf_token()).'"><input type="hidden" name="do" value="transfer_create"><label>Gudang asal<select name="from_warehouse_id" required>';foreach($wh as $w)echo '<option value="'.e($w['id']).'">'.e($w['warehouse_code'].' · '.$w['name']).'</option>';echo '</select></label><label>Gudang tujuan<select name="to_warehouse_id" required>';foreach($wh as $w)echo '<option value="'.e($w['id']).'">'.e($w['warehouse_code'].' · '.$w['name']).'</option>';echo '</select></label><label>Barcode / SKU scan<input class="product-code-scan" data-product-target="transfer-product" placeholder="Scan barcode / QR / SKU" autocomplete="off"></label><label>Produk<select id="transfer-product" name="product_id" required>';foreach($products as $v)echo '<option value="'.e($v['id']).'" data-sku="'.e($v['sku']).'" data-barcode="'.e($v['barcode']??'').'">'.e($v['sku'].' · '.$v['name']).'</option>';echo '</select></label><label>Qty *<input type="number" name="qty" min="0.001" step="0.001" required></label><label>Lokasi asal<select name="from_location_id"><option value="">Otomatis</option>';foreach($p->query('SELECT id,warehouse_id,location_code FROM locations WHERE is_active=1') as $l)echo '<option value="'.e($l['id']).'">'.e($l['location_code'].' (#'.$l['warehouse_id'].')').'</option>';echo '</select></label><label>Lokasi tujuan<select name="to_location_id"><option value="">Tanpa lokasi spesifik</option>';foreach($p->query('SELECT id,warehouse_id,location_code FROM locations WHERE is_active=1') as $l)echo '<option value="'.e($l['id']).'">'.e($l['location_code'].' (#'.$l['warehouse_id'].')').'</option>';echo '</select></label><label class="span-2">Catatan<input name="notes"></label><div><button class="btn primary">Buat & dispatch transfer</button></div></form><p class="muted">Transfer diposting sebagai pengurangan gudang asal dan penambahan gudang tujuan dalam satu transaksi database.</p></section><section class="panel"><h3>Riwayat transfer</h3>'; $rows=$p->query('SELECT t.transfer_no,w1.name from_warehouse,w2.name to_warehouse,t.status,t.requested_at,t.received_at FROM transfers t JOIN warehouses w1 ON w1.id=t.from_warehouse_id JOIN warehouses w2 ON w2.id=t.to_warehouse_id ORDER BY t.requested_at DESC')->fetchAll();table(['Nomor','Gudang asal','Gudang tujuan','Status','Dibuat','Diterima'],array_map(fn($r)=>[$r['transfer_no'],$r['from_warehouse'],$r['to_warehouse'],$r['status'],$r['requested_at'],$r['received_at']?:'—'],$rows));echo '</section>';}
function page_reports(PDO $p):void{$from=$_GET['from']??date('Y-m-01');$to=$_GET['to']??date('Y-m-t');page_title('Laporan & analitik','Ringkasan pergerakan inventory berdasarkan periode.','<div class="toolbar no-print"><button class="btn secondary" type="button" onclick="window.print()">▤ Print</button><a class="btn secondary" href="?action=export&amp;from='.e($from).'&amp;to='.e($to).'">⇩ Excel / CSV</a><button class="btn secondary" type="button" onclick="copyReportForSheets()">▦ Google Sheets</button></div>');echo '<section class="panel no-print"><div class="export-help"><b>Ekspor laporan</b><span>Excel/CSV mengunduh seluruh baris sesuai periode. Untuk Google Sheets, unduh CSV lalu impor ke spreadsheet baru.</span><a class="btn secondary" target="_blank" rel="noopener" href="https://sheets.new">Buka Google Sheets ↗</a></div><form method="get" class="filter-form"><input type="hidden" name="action" value="reports"><label>Dari tanggal<input type="date" name="from" value="'.e($from).'" required></label><label>Sampai tanggal<input type="date" name="to" value="'.e($to).'" required></label><button class="btn secondary">Terapkan</button></form></section>';$st=$p->prepare("SELECT COUNT(*) movements,COALESCE(SUM(CASE WHEN qty_change>0 THEN qty_change ELSE 0 END),0) qty_in,COALESCE(SUM(CASE WHEN qty_change<0 THEN -qty_change ELSE 0 END),0) qty_out,COUNT(DISTINCT product_id) skus FROM stock_movements WHERE occurred_at>=? AND occurred_at<?");$st->execute([$from.' 00:00:00',date('Y-m-d',strtotime($to.' +1 day')).' 00:00:00']);$s=$st->fetch();echo '<div class="stat-grid"><div class="stat-card"><span>Total transaksi</span><strong>'.number_format($s['movements']).'</strong><small>Dalam periode terpilih</small></div><div class="stat-card"><span>Total barang masuk</span><strong>'.number_format((float)$s['qty_in'],3,',','.').'</strong><small>Unit bertambah</small></div><div class="stat-card"><span>Total barang keluar</span><strong>'.number_format((float)$s['qty_out'],3,',','.').'</strong><small>Unit berkurang</small></div><div class="stat-card"><span>SKU bergerak</span><strong>'.number_format($s['skus']).'</strong><small>Produk unik</small></div></div><section class="panel"><div class="panel-head"><div><h3>Detail pergerakan</h3><p>'.e($from).' sampai '.e($to).'</p></div></div>';$st=$p->prepare('SELECT sm.occurred_at,sm.movement_no,sm.movement_type,p.sku,p.name product_name,w.name warehouse_name,sm.qty_change,sm.reference_no,sm.notes FROM stock_movements sm JOIN products p ON p.id=sm.product_id JOIN warehouses w ON w.id=sm.warehouse_id WHERE sm.occurred_at>=? AND sm.occurred_at<? ORDER BY sm.occurred_at DESC');$st->execute([$from.' 00:00:00',date('Y-m-d',strtotime($to.' +1 day')).' 00:00:00']);$rows=$st->fetchAll();table(['Waktu','Nomor','Jenis','SKU','Produk','Gudang','Qty','Referensi','Catatan'],array_map(fn($r)=>[date('d/m/Y H:i',strtotime($r['occurred_at'])),$r['movement_no'],$r['movement_type'],$r['sku'],$r['product_name'],$r['warehouse_name'],qty_fmt($r['qty_change']),$r['reference_no']??'—',$r['notes']?:'—'],$rows));echo '</section>';}

function page_reconciliation(PDO $p):void{
  page_title('Rekonsiliasi Stok','Bandingkan saldo inventory dengan hasil penjumlahan ledger per produk, gudang, lokasi, dan batch.','<div class="toolbar no-print"><button class="btn secondary" type="button" onclick="window.print()">▤ Print</button><a class="btn secondary" href="?action=export">⇩ Ekspor ledger CSV</a></div>');
  $sql="SELECT k.product_id,k.warehouse_id,k.location_id,k.batch_id,p.sku,p.name product_name,w.name warehouse_name,l.location_code,b.batch_no,COALESCE(i.qty_on_hand,0) inventory_qty,COALESCE(m.ledger_qty,0) ledger_qty,COALESCE(i.qty_on_hand,0)-COALESCE(m.ledger_qty,0) difference FROM (SELECT product_id,warehouse_id,location_id,batch_id FROM inventory UNION SELECT product_id,warehouse_id,location_id,batch_id FROM stock_movements) k LEFT JOIN (SELECT product_id,warehouse_id,location_id,batch_id,SUM(qty_on_hand) qty_on_hand FROM inventory GROUP BY product_id,warehouse_id,location_id,batch_id) i ON i.product_id=k.product_id AND i.warehouse_id=k.warehouse_id AND i.location_id <=> k.location_id AND i.batch_id <=> k.batch_id LEFT JOIN (SELECT product_id,warehouse_id,location_id,batch_id,SUM(qty_change) ledger_qty FROM stock_movements GROUP BY product_id,warehouse_id,location_id,batch_id) m ON m.product_id=k.product_id AND m.warehouse_id=k.warehouse_id AND m.location_id <=> k.location_id AND m.batch_id <=> k.batch_id JOIN products p ON p.id=k.product_id JOIN warehouses w ON w.id=k.warehouse_id LEFT JOIN locations l ON l.id=k.location_id LEFT JOIN product_batches b ON b.id=k.batch_id WHERE ABS(COALESCE(i.qty_on_hand,0)-COALESCE(m.ledger_qty,0)) > 0.0005 ORDER BY p.sku,w.name,l.location_code,b.batch_no";
  $rows=$p->query($sql)->fetchAll();
  $summary=$p->query("SELECT (SELECT COUNT(*) FROM inventory) inventory_rows,(SELECT COUNT(*) FROM stock_movements) ledger_rows,(SELECT COUNT(*) FROM stock_movements WHERE reference_type IS NULL OR reference_id IS NULL OR reference_no IS NULL) incomplete_refs")->fetch();
  echo '<div class="stat-grid"><div class="stat-card"><span>Baris inventory</span><strong>'.number_format((int)$summary['inventory_rows']).'</strong><small>Saldo tersimpan</small></div><div class="stat-card"><span>Baris ledger</span><strong>'.number_format((int)$summary['ledger_rows']).'</strong><small>Pergerakan tercatat</small></div><div class="stat-card"><span>Selisih saldo</span><strong>'.number_format(count($rows)).'</strong><small>'.(count($rows)===0?'Saldo dan ledger cocok':'Perlu investigasi').'</small></div><div class="stat-card"><span>Referensi belum lengkap</span><strong>'.number_format((int)$summary['incomplete_refs']).'</strong><small>Perlu ditelusuri</small></div></div>';
  if(count($rows)===0) echo '<section class="panel"><div class="alert success">Tidak ditemukan selisih inventory vs ledger pada kombinasi stok yang tercatat.</div><p class="muted">Pastikan seluruh saldo awal juga dicatat sebagai pergerakan OPENING. Laporan ini hanya memeriksa konsistensi data yang tersimpan.</p></section>';
  else echo '<section class="panel"><div class="alert error">Ditemukan '.count($rows).' kombinasi stok yang tidak cocok. Jangan melakukan koreksi otomatis; investigasi transaksi sumber terlebih dahulu.</div>';
  table(['SKU','Produk','Gudang','Lokasi','Batch','Saldo inventory','Saldo ledger','Selisih'],array_map(fn($r)=>[$r['sku'],$r['product_name'],$r['warehouse_name'],$r['location_code']?:'—',$r['batch_no']?:'—',qty_fmt($r['inventory_qty']),qty_fmt($r['ledger_qty']),qty_fmt($r['difference'])],$rows));
  if(count($rows)>0) echo '</section>';
  echo '<section class="panel"><h3>Aturan rekonsiliasi</h3><ul><li>Saldo inventory harus sama dengan jumlah seluruh qty_change ledger untuk setiap produk/gudang/lokasi/batch.</li><li>Transfer yang langsung diterima harus menghasilkan pasangan TRANSFER_OUT dan TRANSFER_IN dengan kuantitas berlawanan dan referensi transfer yang sama.</li><li>Saldo awal yang dimasukkan manual tanpa movement OPENING akan terdeteksi sebagai selisih.</li><li>Jangan mengedit saldo inventory langsung untuk menghilangkan selisih; buat transaksi koreksi yang memiliki referensi dan audit.</li></ul></section>';
}

function page_audit(PDO $p):void{page_title('Log audit','Jejak perubahan dan aktivitas untuk keperluan penelusuran.');$rows=$p->query('SELECT a.created_at,u.username,a.action,a.entity_type,a.entity_id,a.ip_address FROM audit_logs a LEFT JOIN users u ON u.id=a.user_id ORDER BY a.created_at DESC LIMIT 300')->fetchAll();table(['Waktu','Pengguna','Aksi','Entitas','ID','IP'],array_map(fn($r)=>[$r['created_at'],$r['username']?:'system',$r['action'],$r['entity_type'],$r['entity_id']?:'—',$r['ip_address']?:'—'],$rows));}

function page_barcode(PDO $p):void{
  $query=trim((string)($_GET['q']??''));
  page_title('Pindai Barcode / QR','Pindai SKU, barcode, atau QR code menggunakan kamera perangkat, atau masukkan kode secara manual.');
  echo '<section class="scanner-hero"><div><span class="scanner-eyebrow">CAMERA SCANNER</span><h3>Pindai produk lebih cepat</h3><p>Izinkan akses kamera saat diminta browser. Pemindaian mendukung QR Code serta barcode umum, termasuk Code 128, Code 39, EAN-13, EAN-8, UPC-A, UPC-E, dan ITF.</p></div><div class="scanner-hero-icon" aria-hidden="true">▦</div></section>';
  echo '<section class="panel scanner-panel"><div class="scanner-toolbar"><div><h3>Kamera pemindai</h3><p class="muted">Kamera hanya aktif setelah Anda menekan tombol Mulai kamera.</p></div><span id="scanner-state" class="scanner-state" role="status" aria-live="polite">Kamera belum aktif</span></div>';
  echo '<div class="scanner-controls"><label>Kamera perangkat<select id="scanner-camera" disabled><option value="">Pilih kamera</option></select></label><button type="button" id="scanner-start" class="btn primary">▣ Mulai kamera</button><button type="button" id="scanner-stop" class="btn secondary" disabled>Hentikan</button></div>';
  echo '<div id="scanner-reader" class="scanner-reader" aria-label="Tampilan kamera untuk pemindaian barcode dan QR code"><div class="scanner-placeholder"><span>▦</span><b>Kamera siap digunakan</b><small>Tekan “Mulai kamera” untuk memberikan izin dan memulai pemindaian.</small></div></div>';
  echo '<div id="scanner-message" class="alert info scanner-message" role="status" aria-live="polite">Tips: gunakan HTTPS atau localhost, izinkan akses kamera, dan arahkan kode agar terlihat jelas.</div>';
  echo '<form id="barcode-search-form" method="get" class="scanner-manual-form"><input type="hidden" name="action" value="barcode"><label>Barcode / SKU<input id="barcode-query" name="q" value="'.e($query).'" placeholder="Scan dengan scanner USB atau ketik kode" autocomplete="off" autofocus></label><button class="btn primary" type="submit">Cari produk</button><button class="btn secondary" type="button" id="scanner-clear">Bersihkan</button></form>';
  echo '<p class="muted scanner-privacy">Pemindaian berjalan di browser. Hasil kode dikirim ke aplikasi hanya saat pencarian dilakukan. Jika kamera tidak tersedia, input manual atau scanner USB tetap dapat digunakan.</p></section>';
  if($query!==''){
    $q=$p->prepare('SELECT p.id,p.sku,p.barcode,p.name,p.uom,p.category,COALESCE(SUM(i.qty_on_hand),0) on_hand,COALESCE(SUM(i.qty_reserved),0) reserved,COALESCE(SUM(i.qty_on_hand-i.qty_reserved),0) available FROM products p LEFT JOIN inventory i ON i.product_id=p.id WHERE p.sku=? OR p.barcode=? GROUP BY p.id,p.sku,p.barcode,p.name,p.uom,p.category ORDER BY p.name');
    $q->execute([$query,$query]);$rows=$q->fetchAll();
    echo '<section class="panel scanner-results"><div class="panel-head"><div><h3>Hasil pencarian</h3><p>Kode: <strong>'.e($query).'</strong></p></div><span class="chip">'.count($rows).' produk</span></div>';
    if($rows){table(['SKU','Barcode','Produk','Kategori','Satuan','On-hand','Reserved','Tersedia'],array_map(fn($v)=>[$v['sku'],$v['barcode']?:'—',$v['name'],$v['category']?:'—',$v['uom'],qty_fmt($v['on_hand']),qty_fmt($v['reserved']),qty_fmt($v['available'])],$rows));}
    else echo '<div class="alert info">Produk dengan SKU atau barcode <strong>'.e($query).'</strong> tidak ditemukan. Periksa kode atau daftarkan barcode pada Master Produk.</div>';
    echo '</section>';
  }
  echo '<script src="https://unpkg.com/html5-qrcode@2.3.8/html5-qrcode.min.js" onerror="this.onerror=null;var s=document.createElement(\'script\');s.src=\'https://cdn.jsdelivr.net/npm/html5-qrcode@2.3.8/html5-qrcode.min.js\';document.head.appendChild(s)"></script><script>
  (function(){
    const startBtn=document.getElementById("scanner-start"),stopBtn=document.getElementById("scanner-stop"),cameraSelect=document.getElementById("scanner-camera"),state=document.getElementById("scanner-state"),message=document.getElementById("scanner-message"),reader=document.getElementById("scanner-reader"),query=document.getElementById("barcode-query"),form=document.getElementById("barcode-search-form"),clearBtn=document.getElementById("scanner-clear");
    if(!startBtn||!reader)return;let scanner=null,running=false,handlingResult=false;
    function setMessage(text,kind){message.textContent=text;message.className="alert scanner-message "+(kind||"info");}
    function setState(text,active){state.textContent=text;state.classList.toggle("is-active",!!active);}
    function friendlyError(err){const raw=String(err&&err.message?err.message:err||"");if(/NotAllowedError|Permission denied|Permission dismissed|denied/i.test(raw))return "Akses kamera ditolak. Izinkan Camera pada pengaturan situs/browser, lalu tekan Mulai kamera kembali.";if(/NotFoundError|No camera|device.*not found/i.test(raw))return "Kamera tidak ditemukan. Periksa kamera perangkat atau gunakan scanner USB/input manual.";if(/NotReadableError|Could not start video source|TrackStartError/i.test(raw))return "Kamera sedang digunakan aplikasi lain atau tidak dapat dibuka. Tutup aplikasi kamera lain lalu coba lagi.";if(!window.isSecureContext)return "Browser memblokir kamera karena koneksi tidak aman. Buka aplikasi melalui HTTPS atau localhost.";return "Kamera gagal dimulai. Pastikan izin kamera diberikan, koneksi aman, dan pustaka scanner dapat dimuat.";}
    async function stopScanner(showStatus=true){if(scanner&&running){try{await scanner.stop();}catch(e){}try{await scanner.clear();}catch(e){}}running=false;handlingResult=false;startBtn.disabled=false;stopBtn.disabled=true;cameraSelect.disabled=false;if(showStatus){setState("Kamera dihentikan",false);setMessage("Kamera sudah dihentikan. Anda dapat memulai lagi atau mencari kode secara manual.","info");}}
    async function loadCameras(){if(!window.Html5Qrcode){setMessage("Pustaka scanner belum termuat. Periksa koneksi internet/pemblokir CDN; pencarian manual tetap tersedia.","error");return [];}try{const devices=await Html5Qrcode.getCameras();cameraSelect.innerHTML="";if(!devices.length){cameraSelect.add(new Option("Kamera tidak ditemukan",""));cameraSelect.disabled=true;setMessage("Browser tidak menemukan kamera. Periksa izin/perangkat atau gunakan scanner USB/input manual.","error");return [];}devices.forEach((d,i)=>cameraSelect.add(new Option(d.label||("Kamera "+(i+1)),d.id)));cameraSelect.disabled=devices.length<2;return devices;}catch(err){setMessage(friendlyError(err),"error");return [];}}
    async function startScanner(){if(running)return;if(!window.isSecureContext){setState("Koneksi tidak aman",false);setMessage("Akses kamera memerlukan HTTPS atau localhost. Jika dibuka melalui IP LAN HTTP, aktifkan HTTPS di server.","error");return;}if(!window.Html5Qrcode){setMessage("Pustaka scanner tidak dapat dimuat. Periksa internet, DNS, atau pemblokir CDN. Anda masih dapat memasukkan kode secara manual.","error");return;}startBtn.disabled=true;setState("Meminta izin kamera…",false);setMessage("Pilih Izinkan pada dialog browser untuk mengaktifkan kamera.","info");try{let devices=await loadCameras();reader.innerHTML="";let cameraId=cameraSelect.value||((devices.find(d=>/back|rear|environment|belakang/i.test(d.label))||devices[0]||{}).id);scanner=new Html5Qrcode("scanner-reader",{verbose:false,formatsToSupport:[Html5QrcodeSupportedFormats.QR_CODE,Html5QrcodeSupportedFormats.CODE_128,Html5QrcodeSupportedFormats.CODE_39,Html5QrcodeSupportedFormats.CODE_93,Html5QrcodeSupportedFormats.EAN_13,Html5QrcodeSupportedFormats.EAN_8,Html5QrcodeSupportedFormats.UPC_A,Html5QrcodeSupportedFormats.UPC_E,Html5QrcodeSupportedFormats.ITF,Html5QrcodeSupportedFormats.CODABAR,Html5QrcodeSupportedFormats.DATA_MATRIX,Html5QrcodeSupportedFormats.PDF_417,Html5QrcodeSupportedFormats.AZTEC]});const config={fps:10,qrbox:(w,h)=>{const side=Math.max(180,Math.min(300,Math.floor(Math.min(w,h)*.78)));return {width:side,height:side};},aspectRatio:1.0,disableFlip:false};await scanner.start(cameraId||{facingMode:"environment"},config,async(decodedText)=>{if(handlingResult||!decodedText)return;handlingResult=true;query.value=decodedText.trim();setState("Kode terbaca",true);setMessage("Kode berhasil dibaca. Membuka hasil pencarian…","success");await stopScanner(false);form.requestSubmit();},()=>{});running=true;startBtn.disabled=true;stopBtn.disabled=false;cameraSelect.disabled=devices.length<2;setState("Kamera aktif · arahkan ke kode",true);setMessage("Kamera aktif. Jaga barcode/QR tetap fokus di dalam area pemindaian.","success");}catch(err){running=false;startBtn.disabled=false;stopBtn.disabled=true;setState("Kamera tidak aktif",false);setMessage(friendlyError(err),"error");try{if(scanner)await scanner.clear();}catch(e){}scanner=null;}}
    startBtn.addEventListener("click",startScanner);stopBtn.addEventListener("click",()=>stopScanner(true));cameraSelect.addEventListener("change",async()=>{if(running){await stopScanner(false);await startScanner();}});clearBtn.addEventListener("click",()=>{query.value="";query.focus();setMessage("Input kode dibersihkan. Kamera tidak berubah.","info");});window.addEventListener("pagehide",()=>{if(scanner&&running){scanner.stop().catch(()=>{});}});
    if(!window.isSecureContext){setState("Perlu HTTPS",false);setMessage("Browser hanya mengizinkan kamera pada HTTPS atau localhost. Pencarian manual tetap tersedia.","error");}else if(!window.Html5Qrcode){setState("Memuat scanner…",false);setTimeout(()=>{if(!window.Html5Qrcode){setState("Scanner offline",false);setMessage("Pustaka scanner tidak termuat. Periksa koneksi internet/pemblokir CDN; gunakan input manual jika diperlukan.","error");}},1500);}else{setState("Kamera belum aktif",false);}
  })();
  </script>';
}
function page_barcode_generator():void{
  page_title('Buat Barcode QR','Buat QR Code atau barcode untuk SKU, kode bin, referensi, dan teks lainnya.','<button type="button" class="btn secondary" id="code-reset">Reset</button>');
  echo '<section class="codegen-hero"><div><span class="codegen-eyebrow">LABEL & IDENTIFIKASI</span><h3>Buat kode siap cetak</h3><p>Masukkan SKU, kode lokasi, atau teks apa pun. Hasil dapat diunduh sebagai PNG atau dicetak sesuai kebutuhan label.</p></div><div class="codegen-hero-mark" aria-hidden="true">▦</div></section>';
  echo '<div class="codegen-layout"><section class="panel codegen-form-panel"><div class="codegen-section-title"><div><h3>Pengaturan kode</h3><p>Sesuaikan konten dan tampilan label.</p></div><span class="codegen-step">01</span></div>';
  echo '<label class="codegen-label" for="code-content">TEKS / SKU / BIN</label><input class="codegen-input" id="code-content" maxlength="500" autocomplete="off" placeholder="Contoh: SKU12345 atau A-01-02">';
  echo '<div class="codegen-control-head"><label class="codegen-label" for="code-type">JENIS KODE</label></div><select class="codegen-input" id="code-type"><option value="qr">QR Code</option><option value="barcode">Barcode (Code 128)</option><option value="both">QR Code + Barcode</option></select>';
  echo '<div class="codegen-control-block"><div class="codegen-control-head"><label class="codegen-label" for="qr-size">UKURAN QR</label><output id="qr-size-value" for="qr-size">220 px</output></div><input type="range" id="qr-size" min="120" max="420" step="10" value="220"><div class="codegen-presets"><button type="button" class="btn secondary" data-size="140" data-target="qr-size">Kecil</button><button type="button" class="btn secondary" data-size="220" data-target="qr-size">Sedang</button><button type="button" class="btn secondary" data-size="320" data-target="qr-size">Besar</button></div></div>';
  echo '<div class="codegen-control-block"><div class="codegen-control-head"><label class="codegen-label" for="label-font-size">UKURAN TEKS LABEL</label><output id="label-font-value" for="label-font-size">16 px</output></div><input type="range" id="label-font-size" min="10" max="28" step="1" value="16"><div class="codegen-presets"><button type="button" class="btn secondary" data-size="12" data-target="label-font-size">Kecil</button><button type="button" class="btn secondary" data-size="16" data-target="label-font-size">Sedang</button><button type="button" class="btn secondary" data-size="22" data-target="label-font-size">Besar</button></div></div>';
  echo '<label class="codegen-checkbox"><input type="checkbox" id="show-label-text" checked><span>Tampilkan teks label saat print</span></label><div class="codegen-actions"><button type="button" class="btn primary" id="code-generate">▦ Generate kode</button><button type="button" class="btn secondary" id="code-download" disabled>⬇ Download PNG</button><button type="button" class="btn secondary" id="code-print" disabled>▣ Print</button></div><p class="codegen-help">Kode dibuat di browser dan tidak mengubah master produk atau saldo stok. Untuk barcode Code 128, gunakan teks yang didukung format barcode.</p></section>';
  echo '<section class="panel codegen-preview-panel"><div class="codegen-section-title"><div><h3>Pratinjau</h3><p>Periksa hasil sebelum mengunduh atau mencetak.</p></div><span class="codegen-step">02</span></div><div class="codegen-preview-stage" id="code-preview-stage"><div class="codegen-empty"><span>▦</span><strong>Preview kode akan muncul di sini</strong><p>Masukkan teks lalu tekan Generate kode.</p></div></div><div class="codegen-preview-meta"><span id="code-status" role="status" aria-live="polite">Menunggu input</span><span id="code-char-count">0 / 500 karakter</span></div></section></div>';
  echo '<script src="https://cdn.jsdelivr.net/npm/qrcodejs@1.0.0/qrcode.min.js" onerror="this.onerror=null;var s=document.createElement(\'script\');s.src=\'https://unpkg.com/qrcodejs@1.0.0/qrcode.min.js\';document.head.appendChild(s)"></script><script src="https://cdn.jsdelivr.net/npm/jsbarcode@3.11.6/dist/JsBarcode.all.min.js" onerror="this.onerror=null;var s=document.createElement(\'script\');s.src=\'https://unpkg.com/jsbarcode@3.11.6/dist/JsBarcode.all.min.js\';document.head.appendChild(s)"></script><script>
  (function(){
    const input=document.getElementById("code-content"),type=document.getElementById("code-type"),qrSize=document.getElementById("qr-size"),fontSize=document.getElementById("label-font-size"),showText=document.getElementById("show-label-text"),stage=document.getElementById("code-preview-stage"),status=document.getElementById("code-status"),count=document.getElementById("code-char-count"),generate=document.getElementById("code-generate"),download=document.getElementById("code-download"),print=document.getElementById("code-print"),reset=document.getElementById("code-reset");
    let generatedText="",generatedType="qr",generatedSize=220,generatedFont=16;
    const setStatus=(text,kind="info")=>{status.textContent=text;status.dataset.kind=kind;};
    function updateControls(){document.getElementById("qr-size-value").textContent=qrSize.value+" px";document.getElementById("label-font-value").textContent=fontSize.value+" px";count.textContent=input.value.length+" / 500 karakter";}
    function emptyPreview(message){stage.innerHTML="<div class=\"codegen-empty\"><span>▦</span><strong>Preview kode akan muncul di sini</strong><p>"+message+"</p></div>";download.disabled=true;print.disabled=true;}
    function renderCode(){const value=input.value.trim();if(!value){setStatus("Masukkan teks atau SKU terlebih dahulu","error");input.focus();return;}if(typeof QRCode==="undefined"||typeof JsBarcode==="undefined"){setStatus("Pustaka generator belum termuat. Periksa koneksi internet atau CDN.","error");return;}generatedText=value;generatedType=type.value;generatedSize=Number(qrSize.value);generatedFont=Number(fontSize.value);stage.innerHTML="";const card=document.createElement("div");card.className="codegen-print-card";card.id="code-print-card";const codes=document.createElement("div");codes.className="codegen-code-stack";
      if(generatedType==="qr"||generatedType==="both"){const holder=document.createElement("div");holder.className="codegen-qr-output";holder.id="generated-qr";codes.appendChild(holder);new QRCode(holder,{text:value,width:generatedSize,height:generatedSize,colorDark:"#111827",colorLight:"#ffffff",correctLevel:QRCode.CorrectLevel.M});}
      if(generatedType==="barcode"||generatedType==="both"){const svg=document.createElementNS("http://www.w3.org/2000/svg","svg");svg.id="generated-barcode";svg.classList.add("codegen-barcode-output");codes.appendChild(svg);try{JsBarcode(svg,value,{format:"CODE128",lineColor:"#111827",width:2,height:Math.max(45,Math.round(generatedSize*.28)),displayValue:true,fontSize:Math.min(18,generatedFont),margin:8});}catch(err){setStatus("Teks ini tidak dapat dibuat sebagai Code 128. Periksa isi kode.","error");emptyPreview("Gunakan teks yang valid untuk barcode.");return;}}
      card.appendChild(codes);const label=document.createElement("div");label.className="codegen-label-text";label.textContent=value;label.style.fontSize=generatedFont+"px";label.hidden=!showText.checked;label.id="generated-label-text";card.appendChild(label);stage.appendChild(card);download.disabled=false;print.disabled=false;setStatus("Kode berhasil dibuat","success");}
    function getCanvas(){const qr=stage.querySelector("#generated-qr canvas");if(qr)return qr;const img=stage.querySelector("#generated-qr img");if(img){const c=document.createElement("canvas");c.width=img.naturalWidth||generatedSize;c.height=img.naturalHeight||generatedSize;c.getContext("2d").drawImage(img,0,0,c.width,c.height);return c;}const svg=stage.querySelector("#generated-barcode");if(!svg)return null;const serialized=new XMLSerializer().serializeToString(svg),blob=new Blob([serialized],{type:"image/svg+xml;charset=utf-8"}),url=URL.createObjectURL(blob);return new Promise((resolve,reject)=>{const img2=new Image();img2.onload=()=>{const c=document.createElement("canvas");c.width=img2.naturalWidth||600;c.height=img2.naturalHeight||160;c.getContext("2d").fillStyle="#fff";c.getContext("2d").fillRect(0,0,c.width,c.height);c.getContext("2d").drawImage(img2,0,0);URL.revokeObjectURL(url);resolve(c);};img2.onerror=()=>{URL.revokeObjectURL(url);reject(new Error("Gagal membuat gambar PNG"));};img2.src=url;});}
    async function downloadPng(){if(!generatedText)return;try{let canvas;if(generatedType==="both"){const qrNode=stage.querySelector("#generated-qr canvas"),barNode=stage.querySelector("#generated-barcode");if(!qrNode||!barNode)throw new Error("Kode belum siap");const serialized=new XMLSerializer().serializeToString(barNode),blob=new Blob([serialized],{type:"image/svg+xml;charset=utf-8"}),url=URL.createObjectURL(blob),barCanvas=await new Promise((resolve,reject)=>{const im=new Image();im.onload=()=>{const c=document.createElement("canvas");c.width=im.naturalWidth||600;c.height=im.naturalHeight||160;c.getContext("2d").fillStyle="#fff";c.getContext("2d").fillRect(0,0,c.width,c.height);c.getContext("2d").drawImage(im,0,0);URL.revokeObjectURL(url);resolve(c);};im.onerror=()=>{URL.revokeObjectURL(url);reject(new Error("Barcode tidak dapat dirender"));};im.src=url;});canvas=document.createElement("canvas");canvas.width=Math.max(qrNode.width,barCanvas.width);canvas.height=qrNode.height+barCanvas.height+24;const ctx=canvas.getContext("2d");ctx.fillStyle="#fff";ctx.fillRect(0,0,canvas.width,canvas.height);ctx.drawImage(qrNode,Math.round((canvas.width-qrNode.width)/2),0);ctx.drawImage(barCanvas,Math.round((canvas.width-barCanvas.width)/2),qrNode.height+24);}else{canvas=getCanvas();if(canvas instanceof Promise)canvas=await canvas;}if(!canvas){setStatus("Tidak ada kode untuk diunduh","error");return;}const a=document.createElement("a");a.download=(generatedType==="qr"?"qr-":generatedType==="barcode"?"barcode-":"qr-barcode-")+generatedText.replace(/[^a-z0-9_-]/gi,"_").slice(0,60)+".png";a.href=canvas.toDataURL("image/png");a.click();setStatus("PNG berhasil diunduh","success");}catch(e){setStatus("PNG gagal dibuat. Coba gunakan Print atau muat ulang halaman.","error");}}
