function page_stock_control(PDO $p):void{
  $warehouseId=max(0,(int)($_GET['warehouse_id']??0));
  $warehouses=$p->query('SELECT id,warehouse_code,name FROM warehouses WHERE is_active=1 ORDER BY name')->fetchAll();
  $valid=array_map(fn($w)=>(int)$w['id'],$warehouses);if($warehouseId>0&&!in_array($warehouseId,$valid,true))$warehouseId=0;
  $where=$warehouseId>0?' AND i.warehouse_id=?':'';
  $sql="SELECT p.id product_id,p.sku,p.name product_name,p.uom,p.safety_stock,p.buffer_stock,p.reorder_point,
    COALESCE(SUM(i.qty_on_hand),0) on_hand,COALESCE(SUM(i.qty_reserved),0) reserved,
    COALESCE(SUM(i.qty_on_hand-i.qty_reserved),0) available,GREATEST(p.safety_stock,p.reorder_point) threshold_qty
    FROM products p LEFT JOIN inventory i ON i.product_id=p.id".($warehouseId>0?' AND i.warehouse_id=?':'')."
    WHERE p.is_active=1 GROUP BY p.id,p.sku,p.name,p.uom,p.safety_stock,p.buffer_stock,p.reorder_point
    HAVING GREATEST(p.safety_stock,p.reorder_point)>0 AND COALESCE(SUM(i.qty_on_hand-i.qty_reserved),0)<=GREATEST(p.safety_stock,p.reorder_point) ORDER BY (COALESCE(SUM(i.qty_on_hand-i.qty_reserved),0)<=0) DESC,(GREATEST(p.safety_stock,p.reorder_point)-COALESCE(SUM(i.qty_on_hand-i.qty_reserved),0)) DESC,p.name";
  $q=$p->prepare($sql);$q->execute($warehouseId>0?[$warehouseId]:[]);$low=$q->fetchAll();
  $expirySql="SELECT p.sku,p.name,b.batch_no,b.expiry_date,w.name warehouse_name,i.qty_on_hand FROM inventory i JOIN products p ON p.id=i.product_id JOIN product_batches b ON b.id=i.batch_id JOIN warehouses w ON w.id=i.warehouse_id WHERE b.expiry_date IS NOT NULL AND b.expiry_date<=DATE_ADD(CURDATE(),INTERVAL 90 DAY) AND i.qty_on_hand>0".($warehouseId>0?' AND i.warehouse_id=?':'')." ORDER BY b.expiry_date LIMIT 200";
  $expiryQ=$p->prepare($expirySql);$expiryQ->execute($warehouseId>0?[$warehouseId]:[]);$expiry=$expiryQ->fetchAll();
  $zero=count(array_filter($low,fn($r)=>(float)$r['available']<=0));
  page_title('Kontrol Stok & Alert','Notifikasi stok menipis dan batch mendekati kedaluwarsa berdasarkan saldo inventaris terkini.');
  echo '<section class="panel"><form method="get" class="filter-form"><input type="hidden" name="action" value="stock-control"><label>Gudang<select name="warehouse_id"><option value="0">Semua gudang</option>';foreach($warehouses as $w)echo '<option value="'.e($w['id']).'"'.((int)$w['id']===$warehouseId?' selected':'').'>'.e($w['warehouse_code'].' · '.$w['name']).'</option>';echo '</select></label><button class="btn primary">Terapkan</button><a class="btn secondary" href="?action=stock-control">Reset</a></form><p class="muted">Ambang per SKU menggunakan nilai terbesar dari safety stock dan reorder point. Reserved dikurangi dari on-hand untuk menghitung stok tersedia. Alert ini berbasis aturan deterministik, bukan prediksi AI.</p></section>';
  echo '<div class="stat-grid"><div class="stat-card"><span>SKU perlu perhatian</span><strong>'.number_format(count($low)).'</strong><small>Stok pada/bawah ambang</small></div><div class="stat-card"><span>Stok tersedia nol</span><strong>'.number_format($zero).'</strong><small>Prioritas segera</small></div><div class="stat-card"><span>SKU aktif</span><strong>'.number_format(count_sql($p,'SELECT COUNT(*) FROM products WHERE is_active=1')).'</strong><small>Master produk</small></div><div class="stat-card"><span>Batch expiry ≤ 90 hari</span><strong>'.number_format(count($expiry)).'</strong><small>Termasuk yang kedaluwarsa</small></div></div>';
  echo '<section class="panel"><div class="panel-head"><div><h3>Notifikasi stok menipis</h3><p>Saldo terkini per SKU dalam gudang yang dipilih.</p></div><span class="chip">'.count($low).' alert</span></div>';
  table(['Prioritas','SKU','Produk','On hand','Reserved','Tersedia','Ambang','UOM','Status'],array_map(function($r){$critical=(float)$r['available']<=0;return [$critical?'KRITIS':'MENIPIS',$r['sku'],$r['product_name'],qty_fmt($r['on_hand']),qty_fmt($r['reserved']),qty_fmt($r['available']),qty_fmt($r['threshold_qty']),$r['uom'],$critical?'Perlu replenishment':'Di bawah ambang'];},$low));
  echo '<p class="muted">Terakhir dihitung: '.e(date('d/m/Y H:i:s')).' WIB. Refresh halaman untuk mengambil commit terbaru. Halaman ini hanya membaca data; replenishment dan adjustment tetap harus melalui transaksi resmi agar ledger dan saldo berubah secara atomik.</p></section><section class="panel"><div class="panel-head"><div><h3>Batch mendekati kedaluwarsa</h3><p>Batch dengan tanggal kedaluwarsa dalam 90 hari ke depan atau telah lewat.</p></div><span class="chip">'.count($expiry).' batch</span></div>';
  table(['SKU','Produk','Batch','Expiry','Gudang','Qty'],array_map(fn($r)=>[$r['sku'],$r['name'],$r['batch_no'],$r['expiry_date'],$r['warehouse_name'],$r['qty_on_hand']],$expiry));echo '</section>';
}
function page_schedule(PDO $p):void{
 $warehouses=$p->query('SELECT id,warehouse_code,name FROM warehouses WHERE is_active=1 ORDER BY name')->fetchAll();
 $orders=$p->query("SELECT o.id,o.order_no,o.direction,o.status,o.warehouse_id,w.name warehouse_name FROM orders o JOIN warehouses w ON w.id=o.warehouse_id WHERE o.status NOT IN ('COMPLETED','DISPATCHED','CANCELLED') AND NOT EXISTS(SELECT 1 FROM appointments a WHERE a.order_id=o.id AND a.status IN ('BOOKED','CHECKED_IN','IN_PROGRESS')) ORDER BY o.created_at DESC LIMIT 300")->fetchAll();
 $docks=$p->query('SELECT d.id,d.dock_code,d.name,d.dock_type,d.warehouse_id,w.name warehouse_name FROM dock_doors d JOIN warehouses w ON w.id=d.warehouse_id WHERE d.is_active=1 ORDER BY w.name,d.dock_code')->fetchAll();
 page_title('Jadwal & Dock','Kelola appointment inbound/outbound, slot dock, kendaraan, check-in, dan proses bongkar/muat.');
 echo '<section class="panel"><div class="panel-head"><div><h3>Jadwalkan appointment</h3><p>Pilih order yang belum memiliki appointment aktif. Stok tidak berubah saat jadwal dibuat.</p></div><span class="chip">'.count($orders).' order tersedia</span></div>';
 if(!$warehouses)echo '<div class="alert info">Tambahkan gudang terlebih dahulu di menu Gudang.</div>';
 if(!$docks)echo '<div class="alert info">Belum ada dock aktif. Tambahkan dock pada formulir pengelolaan dock di bawah.</div>';
 echo '<form method="post" class="form-grid"><input type="hidden" name="_csrf" value="'.e(csrf_token()).'"><input type="hidden" name="do" value="appointment_create"><label class="span-2">Order *<select name="order_id" required><option value="">Pilih order...</option>';foreach($orders as $o)echo '<option value="'.e($o['id']).'">'.e($o['order_no'].' · '.$o['direction'].' · '.$o['warehouse_name'].' · '.$o['status']).'</option>';echo '</select></label><label>Dock *<select name="dock_id" required><option value="">Pilih dock...</option>';foreach($docks as $d)echo '<option value="'.e($d['id']).'">'.e($d['warehouse_name'].' · '.$d['dock_code'].' · '.$d['name'].' ('.$d['dock_type'].')').'</option>';echo '</select></label><label>Mulai *<input type="datetime-local" name="starts_at" required></label><label>Selesai *<input type="datetime-local" name="ends_at" required></label><label>Carrier / ekspedisi<input name="carrier" maxlength="120"></label><label>Nomor kendaraan<input name="vehicle_no" maxlength="40"></label><label>Nama pengemudi<input name="driver_name" maxlength="120"></label><label class="span-2">Catatan appointment<input name="appointment_notes" maxlength="500"></label><div><button class="btn primary" '.(!$orders||!$docks?'disabled':'').'>＋ Buat appointment</button></div></form></section>';
 echo '<section class="panel"><div class="panel-head"><div><h3>Dock aktif</h3><p>Dock terikat ke satu gudang; sistem menolak bentrok slot pada dock yang sama.</p></div></div><form method="post" class="form-grid"><input type="hidden" name="_csrf" value="'.e(csrf_token()).'"><input type="hidden" name="do" value="dock_add"><label>Gudang *<select name="warehouse_id" required>';foreach($warehouses as $w)echo '<option value="'.e($w['id']).'">'.e($w['warehouse_code'].' · '.$w['name']).'</option>';echo '</select></label><label>Kode dock *<input name="dock_code" placeholder="DOCK-01" required maxlength="40"></label><label>Nama dock *<input name="dock_name" placeholder="Dock Penerimaan 1" required maxlength="120"></label><label>Tipe *<select name="dock_type"><option value="BOTH">Inbound & Outbound</option><option value="INBOUND">Inbound saja</option><option value="OUTBOUND">Outbound saja</option></select></label><div><button class="btn secondary" '.(!$warehouses?'disabled':'').'>Tambah dock</button></div></form></section>';
 $rows=$p->query("SELECT a.id,a.appointment_no,o.order_no,o.direction,o.status order_status,a.starts_at,a.ends_at,a.status appointment_status,a.carrier,a.vehicle_no,a.driver_name,d.dock_code,d.name dock_name,w.name warehouse_name FROM appointments a JOIN orders o ON o.id=a.order_id JOIN dock_doors d ON d.id=a.dock_id JOIN warehouses w ON w.id=d.warehouse_id ORDER BY a.starts_at DESC LIMIT 300")->fetchAll();
 echo '<section class="panel"><div class="panel-head"><div><h3>Daftar appointment</h3><p>Transisi status: Booked → Check-in → In progress → Completed.</p></div><span class="chip">'.count($rows).' jadwal</span></div><div class="table-wrap"><table><thead><tr><th>Appointment / Order</th><th>Gudang / Dock</th><th>Waktu</th><th>Kendaraan</th><th>Status</th><th>Aksi</th></tr></thead><tbody>';if(!$rows)echo '<tr><td colspan="6" class="empty">Belum ada appointment. Buat jadwal melalui formulir di atas.</td></tr>';foreach($rows as $r){echo '<tr><td><b>'.e($r['appointment_no']).'</b><br>'.e($r['order_no'].' · '.$r['direction']).'</td><td>'.e($r['warehouse_name'].' / '.$r['dock_code'].' · '.$r['dock_name']).'</td><td>'.e(date('d/m/Y H:i',strtotime($r['starts_at'])).' – '.date('H:i',strtotime($r['ends_at']))).'</td><td>'.e(($r['carrier']?:'—').' / '.($r['vehicle_no']?:'—')).'</td><td>'.e($r['appointment_status']).'</td><td><form method="post" class="inline-form"><input type="hidden" name="_csrf" value="'.e(csrf_token()).'"><input type="hidden" name="do" value="appointment_status"><input type="hidden" name="appointment_id" value="'.e($r['id']).'"><select name="next_status">';$next=['BOOKED'=>['CHECKED_IN'=>'Check-in','CANCELLED'=>'Batalkan'],'CHECKED_IN'=>['IN_PROGRESS'=>'Mulai bongkar/muat'],'IN_PROGRESS'=>['COMPLETED'=>'Selesaikan'],'COMPLETED'=>[],'CANCELLED'=>[]];foreach(($next[$r['appointment_status']]??[]) as $v=>$label)echo '<option value="'.e($v).'">'.e($label).'</option>';echo '</select><button class="btn small" '.(empty($next[$r['appointment_status']])?'disabled':'').'>Simpan</button></form></td></tr>';}echo '</tbody></table></div></section>';
}

function page_map(PDO $p):void{
  $warehouses=$p->query('SELECT id,warehouse_code,name FROM warehouses WHERE is_active=1 ORDER BY name')->fetchAll();
  $selected=(int)($_GET['warehouse_id']??($warehouses[0]['id']??0));
  $current=null;foreach($warehouses as $w){if((int)$w['id']===$selected){$current=$w;break;}}
  if(!$current && $warehouses){$current=$warehouses[0];$selected=(int)$current['id'];}
  page_title('Peta Gudang','Visualisasi hierarki lokasi aktual berdasarkan zona, aisle, rack, shelf, dan bin.');
  echo '<section class="panel map-filter-panel"><form method="get" class="filter-form"><input type="hidden" name="action" value="map"><label>Pilih gudang<select name="warehouse_id" onchange="this.form.submit()">';
  foreach($warehouses as $w)echo '<option value="'.e($w['id']).'"'.((int)$w['id']===$selected?' selected':'').'>'.e($w['warehouse_code'].' · '.$w['name']).'</option>';
  echo '</select></label><noscript><button class="btn primary">Tampilkan peta</button></noscript><a class="btn secondary" href="?action=locations">Kelola lokasi</a></form></section>';
  if(!$current){echo '<section class="panel"><div class="empty-state"><div class="empty-state-icon">🏭</div><h3>Belum ada gudang aktif</h3><p>Buat gudang dan lokasi terlebih dahulu agar peta dapat divisualisasikan.</p><a class="btn primary" href="?action=warehouses">Tambah gudang</a></div></section>';return;}
  $st=$p->prepare('SELECT l.id,l.location_code,l.zone,l.aisle,l.rack,l.shelf,l.bin_code,l.location_type,l.is_active,COALESCE(SUM(i.qty_on_hand),0) qty_on_hand,COALESCE(SUM(i.qty_reserved),0) qty_reserved,COUNT(DISTINCT CASE WHEN i.qty_on_hand>0 THEN i.product_id END) sku_count FROM locations l LEFT JOIN inventory i ON i.location_id=l.id AND i.warehouse_id=l.warehouse_id WHERE l.warehouse_id=? GROUP BY l.id ORDER BY l.zone,l.aisle,l.rack,l.shelf,l.bin_code,l.location_code');
  $st->execute([$selected]);$locations=$st->fetchAll();
  $active=0;$occupied=0;$qty=0.0;$zones=[];$aisles=[];
  foreach($locations as $l){if((int)$l['is_active'])$active++;if((float)$l['qty_on_hand']>0)$occupied++;$qty+=(float)$l['qty_on_hand'];$z=trim((string)$l['zone'])?:'Tanpa zona';$a=trim((string)$l['aisle'])?:'Tanpa aisle';$r=trim((string)$l['rack'])?:'Tanpa rack';$sh=trim((string)$l['shelf'])?:'Tanpa shelf';$zones[$z][$a][$r][$sh][]=$l;$aisles[$a]=true;}
  $rate=$active?round($occupied/$active*100):0;
  echo '<div class="map-summary-grid"><div class="map-summary-card map-blue"><span>Zona</span><strong>'.count($zones).'</strong><small>Kelompok zona terdata</small></div><div class="map-summary-card map-violet"><span>Lokasi aktif</span><strong>'.$active.'</strong><small>Dari '.count($locations).' lokasi</small></div><div class="map-summary-card map-green"><span>Lokasi berisi stok</span><strong>'.$occupied.'</strong><small>'.number_format($rate,1,',','.').'% lokasi aktif terisi</small></div><div class="map-summary-card map-orange"><span>Total stok</span><strong>'.number_format($qty,3,',','.').'</strong><small>Qty on-hand · semua SKU</small></div></div>';
  echo '<section class="panel map-legend-panel"><div class="panel-head"><div><h3>'.e($current['warehouse_code'].' · '.$current['name']).'</h3><p>Peta dibuat dari master lokasi dan saldo inventaris aktual, bukan layout simulasi.</p></div><div class="map-legend"><span><i class="legend-location occupied"></i> Ada stok</span><span><i class="legend-location empty"></i> Kosong</span><span><i class="legend-location inactive"></i> Nonaktif</span></div></div>';
  if(!$locations){echo '<div class="empty-state"><div class="empty-state-icon">🗺️</div><h3>Lokasi belum dikonfigurasi</h3><p>Tambahkan lokasi dengan kode, zona, aisle, rack, shelf, dan bin untuk mulai membangun peta.</p><a class="btn primary" href="?action=locations">＋ Tambah lokasi</a></div>';}else{
    foreach($zones as $zone=>$aisleRows){echo '<article class="map-zone"><header class="map-zone-header"><span class="map-zone-mark">▦</span><div><h3>'.e($zone).'</h3><p>'.count($aisleRows).' aisle · '.array_sum(array_map(fn($rackRows)=>array_sum(array_map(fn($shelves)=>array_sum(array_map('count',$shelves)),$rackRows)),$aisleRows)).' lokasi</p></div></header>';
      foreach($aisleRows as $aisle=>$rackRows){echo '<section class="map-aisle"><div class="map-aisle-label"><span>AISLE</span><strong>'.e($aisle).'</strong></div><div class="map-racks">';
        foreach($rackRows as $rack=>$shelfRows){echo '<div class="map-rack"><div class="map-rack-title"><span>RACK</span><strong>'.e($rack).'</strong></div>';
          foreach($shelfRows as $shelf=>$bins){echo '<div class="map-shelf"><div class="map-shelf-label">Shelf '.e($shelf).'</div><div class="map-bins">';
            foreach($bins as $l){$isActive=(int)$l['is_active']===1;$hasStock=(float)$l['qty_on_hand']>0;$class=!$isActive?'inactive':($hasStock?'occupied':'empty');$tip=$l['location_code'].' · '.$l['location_type'].' · On hand: '.qty_fmt($l['qty_on_hand']);echo '<div class="map-bin '.$class.'" title="'.e($tip).'"><strong>'.e($l['bin_code']?:$l['location_code']).'</strong><span>'.e($l['location_code']).'</span><small>'.e($l['location_type']).'</small><b>'.qty_fmt($l['qty_on_hand']).'</b>'.(!$isActive?'<em>Nonaktif</em>':($hasStock?'<em>'.(int)$l['sku_count'].' SKU</em>':'<em>Kosong</em>')).'</div>';}
            echo '</div></div>';}
          echo '</div>';}
        echo '</div></section>';}
      echo '</article>';}
  }
  echo '</section><section class="panel"><div class="panel-head"><div><h3>Detail lokasi</h3><p>Saldo on-hand dan reserved dihitung dari tabel inventory; peta ini tidak mengubah transaksi stok.</p></div><span class="chip">'.count($locations).' lokasi</span></div>';
  table(['Kode lokasi','Zona','Aisle','Rack','Shelf','Bin','Tipe','On hand','Reserved','SKU','Status'],array_map(fn($l)=>[$l['location_code'],$l['zone']?:'—',$l['aisle']?:'—',$l['rack']?:'—',$l['shelf']?:'—',$l['bin_code']?:'—',$l['location_type'],qty_fmt($l['qty_on_hand']),qty_fmt($l['qty_reserved']),$l['sku_count'],(int)$l['is_active']?'Aktif':'Nonaktif'],$locations));echo '</section>';
}

function page_analytics(PDO $p):void{
  $from=(string)($_GET['from']??date('Y-m-01'));
  $to=(string)($_GET['to']??date('Y-m-d'));
  if(!preg_match('/^\d{4}-\d{2}-\d{2}$/',$from)||!preg_match('/^\d{4}-\d{2}-\d{2}$/',$to)||$from>$to){$from=date('Y-m-01');$to=date('Y-m-d');}
  $warehouseId=max(0,(int)($_GET['warehouse_id']??0));
  $warehouses=$p->query('SELECT id,warehouse_code,name FROM warehouses WHERE is_active=1 ORDER BY name')->fetchAll();
  $validIds=array_map(fn($w)=>(int)$w['id'],$warehouses);if($warehouseId!==0&&!in_array($warehouseId,$validIds,true))$warehouseId=0;
  $dateStart=$from.' 00:00:00';$dateEnd=date('Y-m-d',strtotime($to.' +1 day')).' 00:00:00';
  $whSql=$warehouseId>0?' AND sm.warehouse_id=?':'';$params=[$dateStart,$dateEnd];if($warehouseId>0)$params[]=$warehouseId;
  $st=$p->prepare("SELECT COUNT(*) movements,COALESCE(SUM(CASE WHEN qty_change>0 AND movement_type IN ('INBOUND','RETURN','TRANSFER_IN','OPENING','ADJUSTMENT') THEN qty_change ELSE 0 END),0) qty_in,COALESCE(SUM(CASE WHEN qty_change<0 AND movement_type IN ('OUTBOUND','TRANSFER_OUT','DAMAGE','ADJUSTMENT') THEN -qty_change ELSE 0 END),0) qty_out,COUNT(DISTINCT product_id) skus,COUNT(DISTINCT performed_by) operators FROM stock_movements sm WHERE sm.occurred_at>=? AND sm.occurred_at<?$whSql");$st->execute($params);$k=$st->fetch();
  $locParams=[];$locWh=$warehouseId>0?' WHERE l.warehouse_id=?':'';if($warehouseId>0)$locParams[]=$warehouseId;
  $st=$p->prepare('SELECT COUNT(DISTINCT l.id) total_locations,COUNT(DISTINCT CASE WHEN l.is_active=1 THEN l.id END) active_locations,COUNT(DISTINCT CASE WHEN l.is_active=1 AND i.qty_on_hand>0 THEN l.id END) occupied_locations,COUNT(DISTINCT CASE WHEN l.capacity_qty IS NOT NULL AND l.capacity_qty>0 THEN l.id END) capacity_locations FROM locations l LEFT JOIN inventory i ON i.location_id=l.id AND i.warehouse_id=l.warehouse_id'.$locWh);$st->execute($locParams);$loc=$st->fetch()?:[];
  $active=(int)($loc['active_locations']??0);$occupied=(int)($loc['occupied_locations']??0);$occupancy=$active>0?round($occupied/$active*100,1):null;
  $ageWh=$warehouseId>0?' AND i.warehouse_id=?':'';$ageParams=[];if($warehouseId>0)$ageParams[]=$warehouseId;
  $st=$p->prepare("SELECT COALESCE(SUM(CASE WHEN DATEDIFF(CURDATE(),COALESCE(b.manufactured_date,b.created_at))>=30 THEN i.qty_on_hand ELSE 0 END),0) age30,COALESCE(SUM(CASE WHEN DATEDIFF(CURDATE(),COALESCE(b.manufactured_date,b.created_at))>=60 THEN i.qty_on_hand ELSE 0 END),0) age60,COALESCE(SUM(CASE WHEN DATEDIFF(CURDATE(),COALESCE(b.manufactured_date,b.created_at))>=90 THEN i.qty_on_hand ELSE 0 END),0) age90,COALESCE(SUM(i.qty_on_hand),0) batch_qty,COUNT(DISTINCT CASE WHEN i.qty_on_hand>0 THEN i.product_id END) batch_skus FROM inventory i JOIN product_batches b ON b.id=i.batch_id WHERE i.qty_on_hand>0$ageWh");$st->execute($ageParams);$aging=$st->fetch()?:[];
  $prodParams=[$dateStart,$dateEnd];$prodWh=$warehouseId>0?' AND sm.warehouse_id=?':'';if($warehouseId>0)$prodParams[]=$warehouseId;
  $st=$p->prepare("SELECT COALESCE(u.name,'Pengguna tidak tercatat') operator_name,COUNT(*) movement_count,COUNT(DISTINCT sm.product_id) sku_count,COALESCE(SUM(ABS(sm.qty_change)),0) handled_qty FROM stock_movements sm LEFT JOIN users u ON u.id=sm.performed_by WHERE sm.occurred_at>=? AND sm.occurred_at<?$prodWh GROUP BY sm.performed_by,u.name ORDER BY movement_count DESC,handled_qty DESC LIMIT 10");$st->execute($prodParams);$productivity=$st->fetchAll();
  $trend=$p->prepare("SELECT DATE(sm.occurred_at) day,COALESCE(SUM(CASE WHEN sm.qty_change>0 THEN sm.qty_change ELSE 0 END),0) qty_in,COALESCE(SUM(CASE WHEN sm.qty_change<0 THEN -sm.qty_change ELSE 0 END),0) qty_out,COUNT(*) movement_count FROM stock_movements sm WHERE sm.occurred_at>=? AND sm.occurred_at<?$whSql GROUP BY DATE(sm.occurred_at) ORDER BY day");$trend->execute($params);$daily=$trend->fetchAll();
  page_title('Analitik Gudang','KPI dihitung dari ledger pergerakan, saldo inventaris, master lokasi, dan batch yang tersedia.');
  echo '<section class="panel analytics-filter"><form method="get" class="filter-form"><input type="hidden" name="action" value="analytics"><label>Dari tanggal<input type="date" name="from" value="'.e($from).'" required></label><label>Sampai tanggal<input type="date" name="to" value="'.e($to).'" required></label><label>Gudang<select name="warehouse_id"><option value="0">Semua gudang aktif</option>';foreach($warehouses as $w)echo '<option value="'.e($w['id']).'"'.((int)$w['id']===$warehouseId?' selected':'').'>'.e($w['warehouse_code'].' · '.$w['name']).'</option>';echo '</select></label><button class="btn primary">Terapkan</button><a class="btn secondary" href="?action=reports&amp;from='.e($from).'&amp;to='.e($to).'">Laporan detail</a></form><p class="muted">Periode transaksi: '.e($from).' sampai '.e($to).'. Aging menggunakan tanggal produksi atau tanggal pembuatan batch, bukan tanggal penerimaan.</p></section>';
  echo '<div class="analytics-kpi-grid"><article class="analytics-kpi kpi-throughput"><span class="analytics-icon">↕</span><small>Throughput masuk</small><strong>'.number_format((float)$k['qty_in'],3,',','.').'</strong><span>Unit tercatat masuk</span></article><article class="analytics-kpi kpi-outbound"><span class="analytics-icon">↗</span><small>Throughput keluar</small><strong>'.number_format((float)$k['qty_out'],3,',','.').'</strong><span>Unit tercatat keluar</span></article><article class="analytics-kpi kpi-occupancy"><span class="analytics-icon">▦</span><small>Okupansi lokasi</small><strong>'.($occupancy===null?'—':number_format($occupancy,1,',','.').'%').'</strong><span>'.$occupied.' dari '.$active.' lokasi aktif terisi</span></article><article class="analytics-kpi kpi-movement"><span class="analytics-icon">⌁</span><small>Aktivitas ledger</small><strong>'.number_format((int)$k['movements']).'</strong><span>'.number_format((int)$k['skus']).' SKU · '.number_format((int)$k['operators']).' operator teridentifikasi</span></article></div>';
  $lowAlerts=stock_alert_rows($p,500);
  $reconSql="SELECT COUNT(*) FROM (SELECT k.product_id,k.warehouse_id,k.location_id,k.batch_id,COALESCE(i.qty_on_hand,0) iq,COALESCE(m.ledger_qty,0) lq FROM (SELECT product_id,warehouse_id,location_id,batch_id FROM inventory UNION SELECT product_id,warehouse_id,location_id,batch_id FROM stock_movements) k LEFT JOIN (SELECT product_id,warehouse_id,location_id,batch_id,SUM(qty_on_hand) qty_on_hand FROM inventory GROUP BY product_id,warehouse_id,location_id,batch_id) i ON i.product_id=k.product_id AND i.warehouse_id=k.warehouse_id AND i.location_id <=> k.location_id AND i.batch_id <=> k.batch_id LEFT JOIN (SELECT product_id,warehouse_id,location_id,batch_id,SUM(qty_change) ledger_qty FROM stock_movements GROUP BY product_id,warehouse_id,location_id,batch_id) m ON m.product_id=k.product_id AND m.warehouse_id=k.warehouse_id AND m.location_id <=> k.location_id AND m.batch_id <=> k.batch_id WHERE ABS(COALESCE(i.qty_on_hand,0)-COALESCE(m.ledger_qty,0))>0.0005) discrepancies";
  $discrepancies=(int)$p->query($reconSql)->fetchColumn();
  echo '<div class="analytics-kpi-grid analytics-secondary-kpis"><article class="analytics-kpi kpi-movement"><small>SKU di bawah ambang · semua gudang</small><strong>'.number_format(count($lowAlerts)).'</strong><span><a href="?action=stock-control">Buka notifikasi stok →</a></span></article><article class="analytics-kpi '.($discrepancies?'kpi-outbound':'kpi-occupancy').'"><small>Selisih inventory vs ledger · global</small><strong>'.number_format($discrepancies).'</strong><span>'.($discrepancies?'Perlu investigasi rekonsiliasi':'Tidak ada selisih terdeteksi').'</span></article></div>';
  echo '<div class="analytics-two-col"><section class="panel"><div class="panel-head"><div><h3>Pergerakan harian</h3><p>Qty positif dan negatif pada ledger</p></div></div>';
  if(!$daily)echo '<div class="empty-state"><div class="empty-state-icon">📉</div><h3>Belum ada pergerakan pada periode ini</h3><p>Grafik akan muncul setelah transaksi stok tercatat.</p></div>';else{$max=1.0;foreach($daily as $d)$max=max($max,(float)$d['qty_in'],(float)$d['qty_out']);echo '<div class="analytics-trend">';foreach($daily as $d){$in=max(2,(int)round((float)$d['qty_in']/$max*100));$out=max(2,(int)round((float)$d['qty_out']/$max*100));echo '<div class="trend-day" title="'.e($d['day'].' · Masuk '.qty_fmt($d['qty_in']).' · Keluar '.qty_fmt($d['qty_out'])).'"><div class="trend-bars"><i class="trend-in" style="height:'.$in.'%"></i><i class="trend-out" style="height:'.$out.'%"></i></div><small>'.e(date('d/m',strtotime($d['day']))).'</small></div>';}echo '</div><div class="chart-legend"><span><i class="legend-dot blue-dot"></i>Masuk</span><span><i class="legend-dot pink-dot"></i>Keluar</span></div>';}
  echo '</section><section class="panel"><div class="panel-head"><div><h3>Aging stok berbasis batch</h3><p>Qty on-hand berdasarkan umur batch</p></div></div><div class="aging-list"><div class="aging-row"><span><i class="aging-dot aging-30"></i>Usia ≥ 30 hari</span><strong>'.number_format((float)($aging['age30']??0),3,',','.').'</strong></div><div class="aging-row"><span><i class="aging-dot aging-60"></i>Usia ≥ 60 hari</span><strong>'.number_format((float)($aging['age60']??0),3,',','.').'</strong></div><div class="aging-row"><span><i class="aging-dot aging-90"></i>Usia ≥ 90 hari</span><strong>'.number_format((float)($aging['age90']??0),3,',','.').'</strong></div></div><p class="muted">Mencakup stok yang terhubung ke batch. Stok tanpa batch tidak dapat diberi umur secara akurat dan tidak masuk angka aging ini.</p></section></div>';
  echo '<div class="analytics-two-col"><section class="panel"><div class="panel-head"><div><h3>Produktivitas operator</h3><p>Jumlah pergerakan dan kuantitas yang tercatat pada periode terpilih</p></div></div>';
  table(['Operator','Pergerakan','SKU unik','Qty ditangani'],array_map(fn($r)=>[$r['operator_name'],number_format((int)$r['movement_count']),number_format((int)$r['sku_count']),number_format((float)$r['handled_qty'],3,',','.')],$productivity));
  echo '</section><section class="panel"><div class="panel-head"><div><h3>Akurasi stok</h3><p>Validasi membutuhkan hasil stock count fisik</p></div></div><div class="accuracy-unavailable"><span class="accuracy-icon">!</span><div><strong>Belum dapat dihitung</strong><p>Skema starter belum menyimpan hasil cycle count atau stok fisik terverifikasi. Persentase akurasi tidak ditampilkan agar tidak menyesatkan.</p><a href="?action=reconciliation">Buka rekonsiliasi stok →</a></div></div><div class="capacity-note"><strong>Utilisasi kapasitas rak</strong><p>'.number_format((int)($loc['capacity_locations']??0)).' lokasi memiliki kapasitas kuantitas yang dikonfigurasi. Persentase kapasitas tidak dihitung lintas SKU dengan satuan berbeda.</p><a href="?action=map">Lihat peta gudang →</a></div></section></div>';
  echo '<section class="panel"><div class="panel-head"><div><h3>Definisi KPI</h3><p>Transparansi sumber dan batasan pengukuran</p></div></div><div class="analytics-definitions"><div><strong>Throughput</strong><p>Jumlah kuantitas positif/negatif yang tercatat di ledger pergerakan dalam periode pilihan.</p></div><div><strong>Okupansi lokasi</strong><p>Lokasi aktif yang memiliki saldo on-hand di atas nol dibagi total lokasi aktif.</p></div><div><strong>Aging</strong><p>Saldo on-hand batch dengan umur ≥30, ≥60, dan ≥90 hari berdasarkan tanggal produksi atau pembuatan batch.</p></div><div><strong>Produktivitas</strong><p>Jumlah baris pergerakan, SKU unik, dan jumlah absolut kuantitas per operator yang tercatat.</p></div></div></section>';
}

function permission_catalog():array{return ['dashboard'=>'Dasbor','inventory'=>'Inventaris','products'=>'Master Produk','movements'=>'Pergerakan Stok','barcode'=>'Pindai Barcode','barcode-generator'=>'Buat Barcode QR','orders'=>'Inbound & Outbound','inbound'=>'Logistik Masuk','schedule'=>'Jadwal Pengiriman','transfers'=>'Transfer','stock-control'=>'Kontrol Stok','labels'=>'Lokasi & Label','warehouses'=>'Gudang','locations'=>'Lokasi Penyimpanan','map'=>'Peta Gudang','reports'=>'Laporan','reconciliation'=>'Rekonsiliasi Stok','analytics'=>'Analitik','suppliers'=>'Pemasok','roles'=>'Peran & Izin','audit'=>'Log Audit','export'=>'Ekspor CSV','rfid-map'=>'Mapping RFID (UID)'];}
function page_roles(PDO $p):void{
  page_title('Peran & Izin','Atur akses menu dan akun pengguna berdasarkan kebutuhan pekerjaan.');
  $roles=$p->query('SELECT r.id,r.name,r.permissions,r.created_at,(SELECT COUNT(*) FROM users u WHERE u.role_id=r.id) user_count FROM roles r ORDER BY r.id')->fetchAll();
  $users=$p->query('SELECT u.id,u.name,u.username,u.role_id,u.is_active,u.last_login_at,r.name role_name FROM users u JOIN roles r ON r.id=u.role_id ORDER BY u.name')->fetchAll();
  $catalog=permission_catalog();
  echo '<div class="role-layout"><section class="panel role-panel"><div class="panel-head"><div><h3>Tambah peran</h3><p>Perizinan berlaku langsung setelah disimpan.</p></div><span class="role-symbol">🛡️</span></div><form method="post" class="role-form"><input type="hidden" name="_csrf" value="'.e(csrf_token()).'"><input type="hidden" name="do" value="role_save"><label>Nama peran<input name="name" maxlength="60" required placeholder="Contoh: Supervisor Gudang"></label><div class="permission-grid"><label class="permission-item permission-all"><input type="checkbox" name="permissions[]" value="*"> <span><b>Akses penuh</b><small>Semua menu termasuk administrasi</small></span></label>';
  foreach($catalog as $key=>$label)echo '<label class="permission-item"><input type="checkbox" name="permissions[]" value="'.e($key).'"> <span>'.e($label).'</span></label>';
  echo '</div><button class="btn primary" type="submit">Simpan peran</button></form></section><section class="panel role-panel"><div class="panel-head"><div><h3>Daftar peran</h3><p>'.count($roles).' peran terdaftar</p></div></div><div class="role-list">';
  foreach($roles as $r){$perms=json_decode((string)($r['permissions']??'[]'),true);if(!is_array($perms))$perms=[];$all=in_array('*',$perms,true);echo '<details class="role-card"><summary><span><b>'.e($r['name']).'</b><small>'.(int)$r['user_count'].' pengguna · '.($all?'Akses penuh':count($perms).' izin').'</small></span><span>Kelola⌄</span></summary><form method="post" class="role-form"><input type="hidden" name="_csrf" value="'.e(csrf_token()).'"><input type="hidden" name="do" value="role_save"><input type="hidden" name="role_id" value="'.(int)$r['id'].'"><label>Nama peran<input name="name" maxlength="60" required value="'.e($r['name']).'"></label><div class="permission-grid"><label class="permission-item permission-all"><input type="checkbox" name="permissions[]" value="*" '.($all?'checked':'').'> <span><b>Akses penuh</b><small>Semua menu termasuk administrasi</small></span></label>';foreach($catalog as $key=>$label)echo '<label class="permission-item"><input type="checkbox" name="permissions[]" value="'.e($key).'" '.(in_array($key,$perms,true)?'checked':'').'> <span>'.e($label).'</span></label>';echo '</div><div class="role-actions"><button class="btn primary" type="submit">Simpan perubahan</button></form><form method="post" onsubmit="return confirm(\'Hapus peran ini? Peran yang masih digunakan tidak dapat dihapus.\')"><input type="hidden" name="_csrf" value="'.e(csrf_token()).'"><input type="hidden" name="do" value="role_delete"><input type="hidden" name="role_id" value="'.(int)$r['id'].'"><button class="btn danger small" type="submit">Hapus peran</button></form></div></details>';}
  echo '</div></section></div><section class="panel role-panel user-panel"><div class="panel-head"><div><h3>Pengguna</h3><p>Buat akun, tetapkan peran, atau nonaktifkan akses.</p></div></div><form method="post" class="user-create-form"><input type="hidden" name="_csrf" value="'.e(csrf_token()).'"><input type="hidden" name="do" value="user_add"><label>Nama lengkap<input name="name" required maxlength="120"></label><label>Username<input name="username" required maxlength="80" autocomplete="off"></label><label>Password awal<input type="password" name="password" required minlength="12" autocomplete="new-password"><small>Minimal 12 karakter</small></label><label>Peran<select name="role_id" required>';foreach($roles as $r)echo '<option value="'.(int)$r['id'].'">'.e($r['name']).'</option>';echo '</select></label><button class="btn primary" type="submit">Tambah pengguna</button></form><div class="table-wrap"><table><thead><tr><th>Pengguna</th><th>Username</th><th>Peran</th><th>Status</th><th>Login terakhir</th><th>Aksi</th></tr></thead><tbody>';
  foreach($users as $u){$isSelf=(int)$u['id']===(int)($_SESSION['user']['id']??0);echo '<tr><td>'.e($u['name']).($isSelf?' <small>(Anda)</small>':'').'</td><td>'.e($u['username']).'</td><td><form method="post" class="user-role-change"><input type="hidden" name="_csrf" value="'.e(csrf_token()).'"><input type="hidden" name="do" value="user_role"><input type="hidden" name="user_id" value="'.(int)$u['id'].'"><select name="role_id" onchange="this.form.submit()">';foreach($roles as $r)echo '<option value="'.(int)$r['id'].'" '.((int)$r['id']===(int)$u['role_id']?'selected':'').'>'.e($r['name']).'</option>';echo '</select></form></td><td><span class="status-pill '.((int)$u['is_active']?'is-active':'is-inactive').'">'.((int)$u['is_active']?'Aktif':'Nonaktif').'</span></td><td>'.e($u['last_login_at']?:'Belum pernah').'</td><td>';if(!$isSelf)echo '<form method="post" onsubmit="return confirm(\'Ubah status akun pengguna ini?\')"><input type="hidden" name="_csrf" value="'.e(csrf_token()).'"><input type="hidden" name="do" value="user_toggle"><input type="hidden" name="user_id" value="'.(int)$u['id'].'"><button class="btn '.((int)$u['is_active']?'danger':'secondary').' small" type="submit">'.((int)$u['is_active']?'Nonaktifkan':'Aktifkan').'</button></form>';else echo '<span class="muted">Akun aktif</span>';echo '</td></tr>';}
  echo '</tbody></table></div></section>';
}
function page_labels(PDO $p):void{
  $warehouses=$p->query('SELECT id,warehouse_code,name FROM warehouses WHERE is_active=1 ORDER BY name')->fetchAll();
  $warehouseId=(int)($_GET['warehouse_id']??0);
  if($warehouseId>0){$wq=$p->prepare('SELECT id,warehouse_code,name FROM warehouses WHERE id=? AND is_active=1');$wq->execute([$warehouseId]);if(!$wq->fetch())$warehouseId=0;}
  $sql='SELECT l.id,l.location_code,l.zone,l.aisle,l.rack,l.shelf,l.bin_code,l.location_type,w.id warehouse_id,w.warehouse_code,w.name warehouse_name FROM locations l JOIN warehouses w ON w.id=l.warehouse_id WHERE l.is_active=1 AND w.is_active=1';
  $args=[];if($warehouseId){$sql.=' AND w.id=?';$args[]=$warehouseId;}$sql.=' ORDER BY w.name,l.zone,l.aisle,l.rack,l.shelf,l.bin_code,l.location_code';$st=$p->prepare($sql);$st->execute($args);$locations=$st->fetchAll();
  $count=count($locations);$whCount=count(array_unique(array_column($locations,'warehouse_id')));
  page_title('Lokasi & Label','Kelola kode lokasi dan cetak label QR/barcode berdasarkan master lokasi aktif.','<button type="button" class="btn primary" id="print-labels">▣ Cetak label terpilih</button>');
  echo '<section class="label-hero"><div><span class="label-eyebrow">WAREHOUSE IDENTIFICATION</span><h3>Label lokasi siap cetak</h3><p>Pilih lokasi, ukuran label, lalu cetak QR code dan barcode untuk ditempel pada bin atau rak.</p></div><div class="label-hero-icon">▦</div></section>';
  echo '<section class="panel"><form method="get" class="filter-form label-toolbar"><input type="hidden" name="action" value="labels"><label>Gudang<select name="warehouse_id"><option value="0">Semua gudang aktif</option>';foreach($warehouses as $w)echo '<option value="'.(int)$w['id'].'"'.($warehouseId===(int)$w['id']?' selected':'').'>'.e($w['warehouse_code'].' · '.$w['name']).'</option>';echo '</select></label><label>Ukuran label<select id="label-size"><option value="small">50 × 30 mm</option><option value="medium" selected>70 × 40 mm</option><option value="large">100 × 50 mm</option></select></label><label>Format kode<select id="label-code-type"><option value="both">QR + Barcode</option><option value="qr">QR Code saja</option><option value="barcode">Barcode saja</option></select></label><button class="btn secondary" type="submit">Terapkan filter</button><button class="btn secondary" type="button" id="select-all-labels">Pilih semua</button><button class="btn secondary" type="button" id="clear-labels">Hapus pilihan</button></form><div class="label-stats"><span><strong>'.number_format($count).'</strong> lokasi aktif ditemukan</span><span><strong>'.number_format($whCount).'</strong> gudang dalam hasil</span><span class="muted">Kode label mengikuti kode lokasi di master.</span></div></section>';
  if(!$locations){echo '<section class="panel"><div class="empty">Belum ada lokasi aktif untuk filter ini. Tambahkan lokasi melalui <a href="?action=locations">Lokasi Penyimpanan</a>.</div></section>';return;}
  echo '<section class="label-list-head"><div><h3>Pratinjau label</h3><p>Pilih label yang akan dicetak. Gunakan skala 100% pada dialog cetak.</p></div><span class="chip">'.number_format($count).' label tersedia</span></section><div class="location-label-grid" id="location-label-grid">';
  foreach($locations as $l){$payload='NUSA-WMS|LOC|'.$l['warehouse_code'].'|'.$l['location_code'];$hierarchy=implode(' · ',array_values(array_filter([$l['zone'],$l['aisle'],$l['rack'],$l['shelf'],$l['bin_code']],fn($v)=>$v!==null&&$v!=='')));echo '<article class="location-label-card" data-label-card data-size="medium"><label class="label-select"><input type="checkbox" class="label-checkbox" checked aria-label="Pilih label '.e($l['location_code']).'"><span>Pilih label</span></label><div class="print-label size-medium" data-print-label><div class="print-label-brand"><span>NUSA WMS</span><small>'.e($l['warehouse_code']).'</small></div><div class="print-label-body"><div class="print-label-info"><strong>'.e($l['location_code']).'</strong><span>'.e($l['location_type']).'</span><small>'.e($hierarchy?:$l['warehouse_name']).'</small></div><div class="qr-holder" data-qr="'.e($payload).'"></div></div><svg class="barcode-holder" data-barcode="'.e($l['location_code']).'"></svg><div class="print-label-footer">'.e($l['warehouse_name']).'</div></div><div class="label-card-meta"><strong>'.e($l['location_code']).'</strong><span>'.e($l['warehouse_name']).'</span><small>'.e($l['location_type']).($hierarchy?' · '.e($hierarchy):'').'</small></div></article>';}
  echo '</div><p class="muted label-note">QR memuat identitas gudang dan kode lokasi, bukan perubahan stok. Barcode menggunakan kode lokasi. Untuk hasil optimal, cetak pada skala 100% dan uji satu label terlebih dahulu.</p>';
  echo '<div id="label-library-status" class="alert info" role="status">Menyiapkan generator QR dan barcode…</div>';
  echo '<script src="https://cdn.jsdelivr.net/npm/qrcodejs@1.0.0/qrcode.min.js"></script><script src="https://cdn.jsdelivr.net/npm/jsbarcode@3.11.6/dist/JsBarcode.all.min.js"></script><script>
  (function(){const grid=document.getElementById("location-label-grid");if(!grid)return;const status=document.getElementById("label-library-status");const cards=Array.from(grid.querySelectorAll("[data-label-card]"));
  function drawCodes(){let qrOk=typeof window.QRCode!=="undefined",barOk=typeof window.JsBarcode!=="undefined";cards.forEach(card=>{const qr=card.querySelector("[data-qr]"),bar=card.querySelector("[data-barcode]");if(qr&&qrOk&&!qr.dataset.done){qr.innerHTML="";new QRCode(qr,{text:qr.dataset.qr,width:76,height:76,colorDark:"#111827",colorLight:"#ffffff",correctLevel:QRCode.CorrectLevel.M});qr.dataset.done="1";}if(bar&&barOk&&!bar.dataset.done){try{JsBarcode(bar,bar.dataset.barcode,{format:"CODE128",lineColor:"#111827",width:1.35,height:27,displayValue:true,fontSize:9,margin:0});bar.dataset.done="1";}catch(e){bar.replaceWith(Object.assign(document.createElement("span"),{className:"barcode-fallback",textContent:bar.dataset.barcode}));}}});if(qrOk&&barOk){status.textContent="QR dan barcode siap. Pilih label lalu tekan Cetak label terpilih.";status.className="alert label-ready";}else{status.textContent="Pustaka QR/barcode belum termuat. Periksa koneksi internet atau pemblokir CDN, lalu muat ulang halaman.";status.className="alert error";}}
  drawCodes();window.addEventListener("load",drawCodes);setTimeout(drawCodes,900);
  const size=document.getElementById("label-size"),type=document.getElementById("label-code-type");function applyOptions(){cards.forEach(card=>{const label=card.querySelector("[data-print-label]");label.classList.remove("size-small","size-medium","size-large");label.classList.add("size-"+size.value);card.dataset.size=size.value;label.classList.toggle("qr-only",type.value==="qr");label.classList.toggle("barcode-only",type.value==="barcode");});}size.addEventListener("change",applyOptions);type.addEventListener("change",applyOptions);
  document.getElementById("select-all-labels").addEventListener("click",()=>cards.forEach(c=>c.querySelector(".label-checkbox").checked=true));document.getElementById("clear-labels").addEventListener("click",()=>cards.forEach(c=>c.querySelector(".label-checkbox").checked=false));
  document.getElementById("print-labels").addEventListener("click",()=>{const selected=cards.filter(c=>c.querySelector(".label-checkbox").checked);if(!selected.length){alert("Pilih minimal satu label untuk dicetak.");return;}cards.forEach(c=>c.classList.toggle("print-selected",c.querySelector(".label-checkbox").checked));document.body.classList.add("printing-location-labels");window.print();setTimeout(()=>{document.body.classList.remove("printing-location-labels");cards.forEach(c=>c.classList.remove("print-selected"));},400);});applyOptions();})();
  </script>';
}

function page_bin_cl(PDO $p):void{
  $warehouses=$p->query("SELECT id,warehouse_code,name FROM warehouses WHERE is_active=1 ORDER BY name")->fetchAll();
  $warehouseId=(int)($_GET['warehouse_id']??0);$term=trim((string)($_GET['q']??''));$status=$_GET['status']??'all';
  $where=[];$args=[];
  if($warehouseId>0){$where[]='l.warehouse_id=?';$args[]=$warehouseId;}
  if($term!==''){$where[]='(l.location_code LIKE ? OR l.zone LIKE ? OR l.aisle LIKE ? OR l.rack LIKE ? OR l.shelf LIKE ? OR l.bin_code LIKE ? OR w.name LIKE ? OR w.warehouse_code LIKE ?)';for($i=0;$i<8;$i++)$args[]='%'.$term.'%';}
  if($status==='active')$where[]='l.is_active=1';elseif($status==='inactive')$where[]='l.is_active=0';
  $sql="SELECT w.warehouse_code,w.name warehouse_name,l.id location_id,l.location_code,l.zone,l.aisle,l.rack,l.shelf,l.bin_code,l.location_type,l.is_active,COALESCE(SUM(i.qty_on_hand),0) qty_on_hand,COALESCE(SUM(i.qty_reserved),0) qty_reserved,COUNT(DISTINCT CASE WHEN i.qty_on_hand>0 THEN i.product_id END) sku_count FROM locations l JOIN warehouses w ON w.id=l.warehouse_id LEFT JOIN inventory i ON i.location_id=l.id";
  if($where)$sql.=' WHERE '.implode(' AND ',$where);$sql.=' GROUP BY l.id,w.id ORDER BY w.name,l.location_code LIMIT 1000';$st=$p->prepare($sql);$st->execute($args);$rows=$st->fetchAll();
  page_title('Data Bin CL','Daftar lokasi/bin dari master lokasi dan saldo inventaris database lokal.');
  echo '<section class="panel"><div class="alert info">Sumber data: database lokal Nusa WMS. Sinkronisasi ke Cloud/Supabase belum dikonfigurasi. Saldo menampilkan jumlah on-hand pada lokasi, bukan data cloud.</div><form method="get" class="form-grid"><input type="hidden" name="action" value="data-bin-cl"><label>Gudang<select name="warehouse_id"><option value="0">Semua gudang</option>';foreach($warehouses as $w)echo '<option value="'.(int)$w['id'].'"'.($warehouseId===(int)$w['id']?' selected':'').'>'.e($w['warehouse_code'].' · '.$w['name']).'</option>';echo '</select></label><label>Cari lokasi / bin<input name="q" value="'.e($term).'" placeholder="Kode lokasi, zona, rack, bin…"></label><label>Status<select name="status"><option value="all"'.($status==='all'?' selected':'').'>Semua</option><option value="active"'.($status==='active'?' selected':'').'>Aktif</option><option value="inactive"'.($status==='inactive'?' selected':'').'>Nonaktif</option></select></label><div class="form-actions"><button class="btn primary">Terapkan filter</button> <a class="btn secondary" href="?action=data-bin-cl">Reset</a> <a class="btn secondary" href="?action=locations">Kelola lokasi</a></div></form><div class="panel-head"><h3>Hasil lokasi</h3><span class="chip">'.count($rows).' lokasi (maks. 1.000)</span></div>';
  table(['Gudang','Kode lokasi','Zona','Aisle','Rack','Shelf','Bin','Tipe','On-hand','Reserved','SKU','Status'],array_map(fn($r)=>[$r['warehouse_code'].' · '.$r['warehouse_name'],$r['location_code'],$r['zone']?:'—',$r['aisle']?:'—',$r['rack']?:'—',$r['shelf']?:'—',$r['bin_code']?:'—',$r['location_type'],qty_fmt($r['qty_on_hand']),qty_fmt($r['qty_reserved']),$r['sku_count'],(int)$r['is_active']?'Aktif':'Nonaktif'],$rows));echo '</section>';
}
function scan_session_schema_ready(PDO $p):bool{
  $q=$p->prepare("SELECT COUNT(*) FROM information_schema.tables WHERE table_schema=DATABASE() AND table_name IN ('scan_sessions','scan_session_events')");
  $q->execute();
  return (int)$q->fetchColumn()===2;
}

function page_pivot_session(PDO $p):void{
  page_title('Rekap Pivot Sesi','Ringkasan sesi pemindaian yang tercatat, dikelompokkan menurut produk, gudang, dan hasil pencocokan.');
  if(!scan_session_schema_ready($p)){
    echo '<section class="panel"><div class="alert warning"><strong>Tabel sesi pemindaian belum tersedia.</strong><p>Menu ini memerlukan tabel <code>scan_sessions</code> dan <code>scan_session_events</code>. Jalankan migrasi satu kali pada database yang sama dengan aplikasi ini.</p><ol><li>Buka phpMyAdmin.</li><li>Pilih database <code>'.e((string)$p->query('SELECT DATABASE()')->fetchColumn()).'</code>.</li><li>Buka tab Import dan pilih <code>database/migrations/20261012_scan_sessions.sql</code> dari paket aplikasi.</li><li>Jalankan import, lalu muat ulang halaman ini.</li></ol><p>Migrasi hanya membuat tabel pencatatan sesi scan dan tidak mengubah saldo inventaris.</p></div></section>';
    return;
  }
  $sessions=$p->query("SELECT s.id,s.session_code,s.session_name,s.status,s.started_at,s.ended_at,u.name operator_name,COUNT(e.id) scan_count,COUNT(DISTINCT e.product_id) sku_count,SUM(CASE WHEN e.product_id IS NOT NULL THEN 1 ELSE 0 END) matched_count FROM scan_sessions s LEFT JOIN users u ON u.id=s.created_by LEFT JOIN scan_session_events e ON e.session_id=s.id GROUP BY s.id ORDER BY s.started_at DESC LIMIT 100")->fetchAll();
  $active=$p->prepare("SELECT id,session_code,session_name FROM scan_sessions WHERE status='OPEN' AND created_by=? ORDER BY started_at DESC LIMIT 1");$active->execute([(int)($_SESSION['user']['id']??0)]);$current=$active->fetch();
  echo '<section class="panel"><div class="alert info">Sesi mencatat hasil scan SKU, barcode, atau UID RFID sebagai aktivitas audit pemindaian. Pencatatan scan tidak mengubah saldo stok dan tidak mem-posting transaksi inventory. Jalankan migrasi <code>database/migrations/20261012_scan_sessions.sql</code> satu kali sebelum menggunakan fitur ini.</div>';
  if(!$current){echo '<h3>Buka sesi pemindaian</h3><form method="post" class="form-grid"><input type="hidden" name="_csrf" value="'.e(csrf_token()).'"><input type="hidden" name="do" value="scan_session_start"><label>Nama sesi *<input name="session_name" required maxlength="120" placeholder="Contoh: Cycle count zona A"></label><div class="form-actions"><button class="btn primary">Mulai sesi</button></div></form>';}
  else{echo '<div class="alert success"><strong>Sesi aktif:</strong> '.e($current['session_code'].' · '.$current['session_name']).'</div><form method="post" class="form-grid"><input type="hidden" name="_csrf" value="'.e(csrf_token()).'"><input type="hidden" name="do" value="scan_session_capture"><input type="hidden" name="session_id" value="'.(int)$current['id'].'"><label class="span-2">Scan SKU / barcode / UID RFID<input name="scan_code" required maxlength="160" autofocus autocomplete="off" placeholder="Scan lalu tekan Enter"></label><div class="form-actions"><button class="btn primary">Catat hasil scan</button></div></form><form method="post" onsubmit="return confirm(\'Tutup sesi pemindaian ini?\')"><input type="hidden" name="_csrf" value="'.e(csrf_token()).'"><input type="hidden" name="do" value="scan_session_close"><input type="hidden" name="session_id" value="'.(int)$current['id'].'"><button class="btn danger">Tutup sesi</button></form>';}
  echo '</section><section class="panel"><div class="panel-head"><h3>Pivot per sesi</h3><span class="chip">'.count($sessions).' sesi terbaru</span></div>';
  table(['Kode sesi','Nama sesi','Operator','Mulai','Selesai','Status','Total scan','SKU unik','Kode cocok'],array_map(fn($r)=>[$r['session_code'],$r['session_name'],$r['operator_name']?:'—',$r['started_at'],$r['ended_at']?:'—',$r['status'],(int)$r['scan_count'],(int)$r['sku_count'],(int)$r['matched_count']],$sessions));
  $selected=(int)($_GET['session_id']??0);if($selected){$q=$p->prepare("SELECT e.scanned_at,e.raw_code,e.match_type,e.match_value,p.sku,p.name product_name,w.name warehouse_name,u.name operator_name FROM scan_session_events e JOIN scan_sessions s ON s.id=e.session_id LEFT JOIN products p ON p.id=e.product_id LEFT JOIN warehouses w ON w.id=e.warehouse_id LEFT JOIN users u ON u.id=e.scanned_by WHERE s.id=? ORDER BY e.scanned_at DESC LIMIT 500");$q->execute([$selected]);$events=$q->fetchAll();echo '<h3>Detail sesi #'.(int)$selected.'</h3>';table(['Waktu','Kode scan','Hasil','SKU','Produk','Gudang','Operator'],array_map(fn($r)=>[$r['scanned_at'],$r['raw_code'],$r['match_type'],$r['sku']?:'—',$r['product_name']?:'—',$r['warehouse_name']?:'—',$r['operator_name']?:'—'],$events));}
  echo '<p class="muted">Pilih sesi untuk melihat detail: ';foreach($sessions as $sess)echo '<a class="btn secondary small" href="?action=pivot-session&amp;session_id='.(int)$sess['id'].'">'.e($sess['session_code']).'</a> ';echo '</p></section>';
}

function page_rfid_map(PDO $p):void{
  page_title('Mapping RFID (UID)','Daftarkan UID tag RFID ke produk agar identifikasi inventaris konsisten.');
  $products=$p->query("SELECT id,sku,name FROM products WHERE is_active=1 ORDER BY sku")->fetchAll();
  echo '<section class="panel"><div class="alert info"><strong>Status reader:</strong> pemetaan UID sudah tersimpan di database. UID dapat dimasukkan manual atau melalui reader yang berperilaku seperti keyboard (keyboard-wedge). Pembacaan langsung dari reader USB/serial/network belum diaktifkan dan memerlukan driver/protokol perangkat.</div>';
  if(!$products){echo '<div class="alert warning">Belum ada produk aktif. Tambahkan produk terlebih dahulu sebelum membuat pemetaan UID.</div>';}
  echo '<h3>Tambah pemetaan UID</h3><form method="post" class="form-grid"><input type="hidden" name="_csrf" value="'.e(csrf_token()).'"><input type="hidden" name="do" value="rfid_mapping_save"><input type="hidden" name="mapping_id" value="0"><label>UID RFID *<input name="uid" required maxlength="160" autocomplete="off" placeholder="Contoh: E200341201234567890ABCDE"></label><label>Produk / SKU *<select name="product_id" required><option value="">Pilih produk</option>';foreach($products as $pr)echo '<option value="'.(int)$pr['id'].'">'.e($pr['sku'].' — '.$pr['name']).'</option>';echo '</select></label><label>Nama reader (opsional)<input name="reader_name" maxlength="120" placeholder="Contoh: Reader Gate A"></label><label class="span-2">Catatan<input name="notes" maxlength="500" placeholder="Area, pintu, atau keterangan pemasangan"></label><div class="span-2"><button class="btn primary" '.(!$products?'disabled':'').'>Simpan pemetaan UID</button></div></form></section>';
  $rows=$p->query('SELECT m.id,m.uid,m.product_id,m.reader_name,m.notes,m.is_active,m.created_at,p.sku,p.name product_name FROM rfid_mappings m JOIN products p ON p.id=m.product_id ORDER BY m.is_active DESC,m.created_at DESC,m.id DESC LIMIT 500')->fetchAll();
  echo '<section class="panel"><div class="panel-head"><div><h3>Daftar pemetaan</h3><p>UID unik; penonaktifan mempertahankan histori audit.</p></div><span class="chip">'.count($rows).' pemetaan</span></div><div class="table-wrap"><table><thead><tr><th>UID RFID</th><th>SKU / Produk</th><th>Reader</th><th>Catatan</th><th>Status</th><th>Aksi</th></tr></thead><tbody>';
  if(!$rows)echo '<tr><td colspan="6" class="empty">Belum ada UID RFID yang dipetakan.</td></tr>';
  foreach($rows as $r){echo '<tr><td><code>'.e($r['uid']).'</code></td><td><strong>'.e($r['sku']).'</strong><br>'.e($r['product_name']).'</td><td>'.e($r['reader_name']?:'—').'</td><td>'.e($r['notes']?:'—').'</td><td>'.((int)$r['is_active']?'<span class="chip">Aktif</span>':'<span class="chip">Nonaktif</span>').'</td><td>';
    if((int)$r['is_active']){echo '<details><summary class="btn secondary">Edit</summary><form method="post" class="form-grid compact-form"><input type="hidden" name="_csrf" value="'.e(csrf_token()).'"><input type="hidden" name="do" value="rfid_mapping_save"><input type="hidden" name="mapping_id" value="'.(int)$r['id'].'"><label>UID *<input name="uid" required maxlength="160" value="'.e($r['uid']).'"></label><label>Produk *<select name="product_id" required>';foreach($products as $pr)echo '<option value="'.(int)$pr['id'].'"'.((int)$pr['id']===(int)$r['product_id']?' selected':'').'>'.e($pr['sku'].' — '.$pr['name']).'</option>';
      echo '</select></label><label>Reader<input name="reader_name" maxlength="120" value="'.e($r['reader_name']??'').'"></label><label>Catatan<input name="notes" maxlength="500" value="'.e($r['notes']??'').'"></label><button class="btn primary">Simpan perubahan</button></form></details><form method="post" onsubmit="return confirm(\'Nonaktifkan pemetaan UID ini?\')"><input type="hidden" name="_csrf" value="'.e(csrf_token()).'"><input type="hidden" name="do" value="rfid_mapping_deactivate"><input type="hidden" name="mapping_id" value="'.(int)$r['id'].'"><label>Alasan <input name="reason" required minlength="5" maxlength="250" placeholder="Alasan nonaktifkan"></label><button class="btn danger">Nonaktifkan</button></form>';}else echo '—';echo '</td></tr>';}
  echo '</tbody></table></div></section>';
}


