function page_fast_slow_dead(PDO $p):void{
  $warehouseId=max(0,(int)($_GET['warehouse_id']??0));
  $warehouses=$p->query('SELECT id,warehouse_code,name FROM warehouses WHERE is_active=1 ORDER BY name')->fetchAll();
  $validIds=array_map(fn($w)=>(int)$w['id'],$warehouses);
  if($warehouseId!==0&&!in_array($warehouseId,$validIds,true))$warehouseId=0;
  $invSql='SELECT product_id,SUM(qty_on_hand) qty_on_hand,SUM(qty_reserved) qty_reserved FROM inventory';
  $movementSql='SELECT product_id,MAX(occurred_at) last_movement FROM stock_movements';
  $params=[];
  if($warehouseId>0){$invSql.=' WHERE warehouse_id=?';$params[]=$warehouseId;$movementSql.=' WHERE warehouse_id=?';$params[]=$warehouseId;}
  $invSql.=' GROUP BY product_id';$movementSql.=' GROUP BY product_id';
  $sql="SELECT p.sku,p.name product_name,COALESCE(i.qty_on_hand,0) qty_on_hand,COALESCE(i.qty_reserved,0) qty_reserved,sm.last_movement,DATEDIFF(CURDATE(),DATE(sm.last_movement)) days_since_movement FROM products p LEFT JOIN ($invSql) i ON i.product_id=p.id LEFT JOIN ($movementSql) sm ON sm.product_id=p.id WHERE p.is_active=1 ORDER BY days_since_movement DESC,p.sku";
  $st=$p->prepare($sql);$st->execute($params);$rows=$st->fetchAll();
  $classified=[];
  foreach($rows as $r){$days=$r['days_since_movement']===null?null:(int)$r['days_since_movement'];$qty=(float)$r['qty_on_hand'];$class=$qty<=0?'Tidak ada stok':($days===null||$days>90?'Dead':($days>30?'Slow':'Fast'));$r['classification']=$class;$r['days_label']=$days===null?'Tidak ada ledger':(string)$days.' hari';$classified[]=$r;}
  page_title('Fast / Slow / Dead Stock','Klasifikasi berbasis transaksi ledger terakhir, bukan perkiraan penjualan.');
  echo '<section class="panel"><form method="get" class="filter-form"><input type="hidden" name="action" value="fast-slow-dead"><label>Gudang<select name="warehouse_id"><option value="0">Semua gudang aktif</option>';
  foreach($warehouses as $w)echo '<option value="'.(int)$w['id'].'"'.((int)$w['id']===$warehouseId?' selected':'').'>'.e($w['warehouse_code'].' · '.$w['name']).'</option>';
  echo '</select></label><button class="btn primary">Terapkan</button><a class="btn secondary" href="?action=fast-slow-dead">Reset</a></form><div class="alert info">Aturan klasifikasi: Fast = transaksi terakhir dalam 30 hari; Slow = 31–90 hari; Dead = lebih dari 90 hari atau belum ada ledger. Produk tanpa stok ditandai terpisah. Ambang ini adalah aturan laporan, bukan standar yang dikonfigurasi.</div>';
  table(['SKU','Produk','On hand','Reserved','Tersedia','Transaksi terakhir','Hari sejak transaksi','Klasifikasi'],array_map(fn($r)=>[$r['sku'],$r['product_name'],qty_fmt($r['qty_on_hand']),qty_fmt($r['qty_reserved']),qty_fmt((float)$r['qty_on_hand']-(float)$r['qty_reserved']),$r['last_movement']?:'—',$r['days_label'],$r['classification']],$classified));
  echo '</section>';
}

function page_movement_tracking(PDO $p):void{
  $from=(string)($_GET['from']??date('Y-m-01'));$to=(string)($_GET['to']??date('Y-m-d'));$sku=trim((string)($_GET['sku']??''));
  if(!preg_match('/^\d{4}-\d{2}-\d{2}$/',$from)||!preg_match('/^\d{4}-\d{2}-\d{2}$/',$to)||$from>$to){$from=date('Y-m-01');$to=date('Y-m-d');}
  $sql='SELECT sm.occurred_at,sm.movement_no,sm.movement_type,p.sku,p.name product_name,w.name warehouse_name,l.location_code,sm.qty_change,sm.reference_no,sm.notes FROM stock_movements sm JOIN products p ON p.id=sm.product_id JOIN warehouses w ON w.id=sm.warehouse_id LEFT JOIN locations l ON l.id=sm.location_id WHERE sm.occurred_at>=? AND sm.occurred_at<?';
  $params=[$from.' 00:00:00',date('Y-m-d',strtotime($to.' +1 day')).' 00:00:00'];if($sku!==''){$sql.=' AND (p.sku LIKE ? OR p.name LIKE ?)';$params[]='%'.$sku.'%';$params[]='%'.$sku.'%';}$sql.=' ORDER BY sm.occurred_at DESC LIMIT 1000';
  $st=$p->prepare($sql);$st->execute($params);$rows=$st->fetchAll();
  page_title('Tracking Movement','Telusuri ledger berdasarkan periode dan SKU.');
  echo '<section class="panel"><form method="get" class="filter-form"><input type="hidden" name="action" value="movement-tracking"><label>Dari tanggal<input type="date" name="from" value="'.e($from).'" required></label><label>Sampai tanggal<input type="date" name="to" value="'.e($to).'" required></label><label>SKU / nama<input name="sku" value="'.e($sku).'" maxlength="200" placeholder="Cari SKU atau nama produk"></label><button class="btn primary">Cari</button><a class="btn secondary" href="?action=movement-tracking">Reset</a></form><p class="muted">Menampilkan maksimal 1.000 transaksi terbaru sesuai filter.</p>';
  table(['Waktu','Nomor','Jenis','SKU','Produk','Gudang','Lokasi','Qty (+/-)','Referensi','Catatan'],array_map(fn($r)=>[$r['occurred_at'],$r['movement_no'],$r['movement_type'],$r['sku'],$r['product_name'],$r['warehouse_name'],$r['location_code']?:'—',qty_fmt($r['qty_change']),$r['reference_no']?:'—',$r['notes']?:'—'],$rows));
  echo '</section>';
}

function page_reference_module(PDO $p,string $action):void{
  $meta=[
    'cycle-count'=>['Cycle Count Bin','Hitung dan verifikasi saldo per bin.','Menu sudah tersedia, tetapi workflow sesi hitung, approval, dan posting selisih belum dibuat agar tidak menghasilkan penyesuaian stok palsu.'],
    'stock-opname'=>['Stock Opname Harian','Pemeriksaan fisik stok dan pencatatan hasil opname.','Gunakan Rekonsiliasi Stok untuk melihat selisih aktual saat ini. Form sesi opname, bukti, dan approval belum diaktifkan.'],
    'pivot-session'=>['Rekap Pivot Sesi','Ringkasan operasional berdasarkan ledger stok yang sudah tersimpan.','Rekap transaksi tersedia pada Laporan. Pivot per sesi membutuhkan identitas sesi scan yang belum ada pada skema database lokal.'],
    'history-cc-transfer'=>['History CC & Transfer','Riwayat transfer gudang dan ledger stok.','Riwayat transfer tersedia pada menu Transfer; riwayat cycle count belum tersedia karena workflow cycle count belum diaktifkan.'],
    'data-induk'=>['Data Induk (Cloud)','Sumber referensi untuk data master inventory.','Koneksi Cloud/Supabase dari aplikasi referensi belum dikonfigurasi pada Nusa WMS. Halaman ini tidak akan menampilkan data contoh atau mengirim perubahan ke layanan eksternal.'],
  ];
  [$title,$desc,$note]=$meta[$action]??['Modul','Operasional inventory','Modul belum tersedia.'];
  page_title($title,$desc);
  echo '<section class="panel"><div class="alert info">'.e($note).'</div>';
  if($action==='history-cc-transfer'){
    $rows=$p->query("SELECT t.transfer_no,w1.name from_warehouse,w2.name to_warehouse,t.status,t.requested_at,t.received_at FROM transfers t JOIN warehouses w1 ON w1.id=t.from_warehouse_id JOIN warehouses w2 ON w2.id=t.to_warehouse_id ORDER BY t.requested_at DESC LIMIT 300")->fetchAll();
    table(['Nomor transfer','Gudang asal','Gudang tujuan','Status','Diminta','Diterima'],array_map(fn($r)=>[$r['transfer_no'],$r['from_warehouse'],$r['to_warehouse'],$r['status'],$r['requested_at'],$r['received_at']?:'—'],$rows));
    echo '<a class="btn secondary" href="?action=transfers">Buka transfer</a>';
  } elseif($action==='pivot-session') {
    echo '<a class="btn primary" href="?action=reports">Buka laporan operasional</a> <a class="btn secondary" href="?action=movements">Lihat ledger pergerakan</a>';
  } elseif($action==='cycle-count'||$action==='stock-opname') {
    echo '<a class="btn primary" href="?action=reconciliation">Buka rekonsiliasi stok</a> <a class="btn secondary" href="?action=inventory">Lihat saldo inventaris</a>';
  } elseif($action==='data-induk') {
    echo '<a class="btn primary" href="?action=products">Master produk lokal</a> <a class="btn secondary" href="?action=warehouses">Master gudang</a>';
  } else {
    echo '<a class="btn primary" href="?action=products">Master produk</a> <a class="btn secondary" href="?action=barcode-generator">Buat Barcode QR</a>';
  }
  echo '</section>';
}

function page_workflow_placeholder(string $action):void{$meta=['inbound'=>['Logistik Masuk','Antrean ASN, penerimaan parsial, pemeriksaan kualitas, dan put-away.','Modul inbound lanjutan perlu workflow ASN/PO, scan batch/serial, dan quality hold.'],'schedule'=>['Jadwal Pengiriman','Rencana dock, slot penerimaan, dan jadwal dispatch.','Modul jadwal akan menghubungkan appointment, carrier, dock door, dan status kedatangan.'],'stock-control'=>['Kontrol Stok','Cycle count, stock adjustment, replenishment, dan alert safety stock.','Dashboard safety stock dasar tersedia di Dasbor; approval cycle count dan replenishment otomatis masih perlu implementasi.'],'labels'=>['Lokasi & Label','Pengelolaan kode lokasi dan format label barcode.','Master lokasi tersedia pada menu Lokasi Penyimpanan. Template cetak label dan QR/barcode siap cetak merupakan tahap lanjutan.'],'roles'=>['Peran & Izin','Kelola peran pengguna dan akses berbasis izin.','Tabel roles/users sudah tersedia. UI manajemen izin granular dan enforcement middleware perlu diselesaikan sebelum produksi.']];[$title,$desc,$note]=$meta[$action]??['Modul','Operasional gudang',''];page_title($title,$desc);echo '<section class="panel"><div class="alert info">'.e($note).'</div><p class="muted">Halaman ini sudah terdaftar pada navigasi, tetapi proses operasional lanjutannya belum diklaim aktif dalam versi starter. Ini menjaga ekspektasi tetap jelas dan menghindari transaksi palsu.</p>';echo '</section>';}

